content:
TCP序列号初始化与回绕处理机制
适用范围：TCP 初始序列号(ISN)生成、32位序列号空间与回绕、after&#x2F;before 比较宏、PAWS 回绕保护、窗口限制与序列号安全性

一、核心概念
定义：TCP 使用 32 位无符号整数作为序列号，空间约 4GB。ISN 基于四元组+时间+密钥的 MD5 哈希随机生成（RFC 6528），防止序列号预测攻击。序列号回绕是 32 位无符号整数自然溢出的行为，不是重新初始化
关键词：ISN、RFC 6528、sequence wrap-around、after&#x2F;before 宏、有符号差值比较、PAWS、TCP Timestamp、窗口限制(2^31)
适用场景&#x2F;边界：
理解 TCP 可靠传输的基础
高速网络（10Gbps+）中 PAWS 时间戳的必要性
边界：仅讨论 TCP 序列号机制，不涉及其他协议



二、详细解析（≥200字）2.1 ISN 生成算法（RFC 6528）ISN 基于连接四元组和时钟生成随机序列号，核心目标：不可预测性、防重放攻击：
// net/ipv4/tcp_ipv4.cu32 secure_tcp_sequence_number(__be32 saddr, __be32 daddr,                              __be16 sport, __be16 dport)&#123;    u32 hash[4];    hash[0] = (__force u32)saddr;    hash[1] = (__force u32)daddr;    hash[2] = ((__force u16)sport &lt;&lt; 16) + (__force u16)dport;    hash[3] = ktime_get_real_ns();        // 时间戳    md5_transform(hash, tcp_secret);       // 内核密钥哈希    return hash[0] + (ktime_get_real_ns() &gt;&gt; 6);  // 每4微秒递增&#125;

2.2 回绕与比较算法序列号回绕是 C 语言无符号整数自然溢出行为：0xFFFFFFFF + 1 = 0x00000000。比较序列号时使用带符号差值：
static inline bool after(u32 seq1, u32 seq2) &#123;    return (s32)(seq1 - seq2) &gt; 0;&#125;static inline bool before(u32 seq1, u32 seq2) &#123;    return (s32)(seq1 - seq2) &lt; 0;&#125;

数学原理：假设任意两个有效序列号的距离不超过 2^31（约 2GB），有符号差值就能正确判断先后。TCP 通过窗口限制（最大窗口 &lt; 2^31 字节）保证这一假设成立。
2.3 PAWS（Protection Against Wrapped Sequences）在高速网络中序列号快速回绕，PAWS 使用 TCP Timestamp 选项辅助判断：相同序列号但时间戳更新的 → 新数据；时间戳更旧的 → 旧数据（丢弃）。PAWS 窗口默认 24 天。
三、动手实践（代码案例）3.1 理解序列号比较#include &lt;stdint.h&gt;#include &lt;stdio.h&gt;bool after(uint32_t seq1, uint32_t seq2) &#123;    return (int32_t)(seq1 - seq2) &gt; 0;&#125;// 测试：100 在时间上晚于接近溢出的大数uint32_t seq1 = 100;uint32_t seq2 = 0xFFFFFF00;printf(&quot;after(100, 0xFFFFFF00) = %d\n&quot;, after(seq1, seq2));// 输出 1 (true)：100 在时间上确实在 0xFFFFFF00 之后// (int32_t)(100 - 0xFFFFFF00) = (int32_t)(0x100) = 256 &gt; 0

3.2 不同带宽下回绕时间计算#include &lt;stdio.h&gt;#include &lt;stdint.h&gt;void calc_wrap_time() &#123;    // 32位 = 4GB = 34,359,738,368 bits    uint64_t seq_bits = (uint64_t)0x100000000ULL * 8;        struct &#123; const char* name; uint64_t bps; &#125; bw[] = &#123;        &#123;&quot;1Gbps&quot;,   1000000000ULL&#125;,        &#123;&quot;10Gbps&quot;, 10000000000ULL&#125;,        &#123;&quot;100Gbps&quot;,100000000000ULL&#125;,    &#125;;        for (int i = 0; i &lt; 3; i++) &#123;        double sec = (double)seq_bits / bw[i].bps;        printf(&quot;%s: 回绕时间 = %.2f 秒\n&quot;, bw[i].name, sec);    &#125;&#125;// 输出：// 1Gbps:   34.36 秒// 10Gbps:   3.44 秒// 100Gbps:  0.34 秒

四、进阶应用（≥500字）4.1 回绕窗口检查实战// TCP 接收窗口检查（处理回绕）bool tcp_sequence_in_window(u32 seq, u32 rcv_nxt, u32 rcv_wnd) &#123;    if (before(seq, rcv_nxt)) return false;                // 左边界之外    if (after_eq(seq, rcv_nxt + rcv_wnd)) return false;    // 右边界之外（rcv_nxt+rcv_wnd 也可能回绕）    return true;&#125;// 示例：窗口起始 rcv_nxt=0xFFFFFF00，窗口大小 65536// 窗口范围: [0xFFFFFF00, 0x0000FF00]（自然回绕）//   0xFFFFFF50 → 在窗口内 ✓//   0x00000050 → 在窗口内 ✓  //   0x0000FF50 → 在窗口外 ✗

4.2 ACK 处理中的回绕int tcp_ack(struct sock *sk, const struct sk_buff *skb, int flag) &#123;    u32 ack = TCP_SKB_CB(skb)-&gt;ack_seq;    u32 prior_snd_una = tp-&gt;snd_una;        if (before(ack, prior_snd_una)) goto duplicate_ack;   // 重复/过时 ACK    if (after(ack, tp-&gt;snd_nxt)) goto invalid_ack;         // 确认了未发送的数据        tp-&gt;snd_una = ack;  // 更新未确认序列号（可能涉及回绕）    // 计算新确认字节数：ack - prior_snd_una（无符号减法自然处理回绕）&#125;

4.3 与其他主题的关联


关联主题
关联点



TCP 三次握手
SYN 携带 ISN，SYN+ACK 携带对端 ISN+1


发送&#x2F;接收队列
序列号决定数据进入哪个队列和排列顺序


拥塞控制
拥塞窗口以序列号空间来衡量发送范围


Socket 缓冲区
接收窗口大小受缓冲区可用空间限制


4.4 常见误区
❌ 序列号回绕时重新生成 ISN → ✅ 自然溢出继续递增
❌ if (seq_num &lt; 0) 处理负数 → ✅ 序列号是 u32 无符号，不存在负数
❌ 高速网络不需要 PAWS → ✅ 100Gbps 下序列号 0.34 秒就回绕，必须 PAWS 辅助

五、源码解析和实践感悟（≥1000字）5.1 连接建立时的 ISN 分配路径// 客户端 connect()int tcp_v4_connect(struct sock *sk, struct sockaddr *uaddr, int addr_len) &#123;    struct tcp_sock *tp = tcp_sk(sk);        // 生成客户端 ISN    tp-&gt;write_seq = secure_tcp_sequence_number(        inet-&gt;inet_saddr, inet-&gt;inet_daddr,        inet-&gt;inet_sport, usin-&gt;sin_port);    tp-&gt;snd_nxt = tp-&gt;write_seq;    tp-&gt;snd_una = tp-&gt;write_seq;    return tcp_connect(sk);&#125;// 服务端收到 SYN 后int tcp_conn_request(...) &#123;    isn = af_ops-&gt;init_seq(skb);  // 生成服务端 ISN    inet_reqsk_alloc(rsk_ops, sk, !want_cookie);    tcp_rsk(req)-&gt;snt_isn = isn;  // 保存 ISN    return tcp_v4_send_synack(sk, dst, &amp;fl4, req, ...);  // SYN+ACK 携带 ISN&#125;

5.2 tcp_write_xmit 中的序列号检查static bool tcp_write_xmit(struct sock *sk, unsigned int mss_now, ...) &#123;    struct tcp_sock *tp = tcp_sk(sk);        while ((skb = tcp_send_head(sk))) &#123;        // 拥塞控制：已发出且未确认的段数 ≥ 拥塞窗口        if (tcp_packets_in_flight(tp) &gt;= tp-&gt;snd_cwnd) return false;                // 序列号在发送窗口内（处理回绕）        if (after(TCP_SKB_CB(skb)-&gt;seq, tp-&gt;snd_una + tp-&gt;snd_wnd))            break;  // 超出发送窗口                tcp_transmit_skb(sk, skb, 1, gfp);        tp-&gt;snd_nxt = TCP_SKB_CB(skb)-&gt;end_seq;  // 可能自然回绕    &#125;&#125;

5.3 PAWS 时间戳验证bool tcp_paws_discard(const struct sock *sk, const struct sk_buff *skb) &#123;    const struct tcp_sock *tp = tcp_sk(sk);        // 时间戳检查：序列号可能回绕，但时间戳必须更新    if (tp-&gt;rx_opt.ts_recent &amp;&amp;        get_seconds() - tp-&gt;rx_opt.ts_recent_stamp &lt; TCP_PAWS_24DAYS &amp;&amp;        TCP_SKB_CB(skb)-&gt;when &lt; tp-&gt;rx_opt.ts_recent) &#123;        return true;  // 丢弃：时间戳倒退，这是已回绕的旧数据    &#125;    return false;&#125;

5.4 实践感悟
after&#x2F;before 宏的设计精妙：将无符号减法结果转为有符号比较，一行代码解决序列号回绕问题。前提是窗口 &lt; 2^31 字节的保证。

为什么序列号空间是 32 位：TCP 设计于 1980 年代，当时带宽远小于今天。32 位 &#x3D; 4GB 足够。今天的高带宽必须依赖 PAWS 时间戳辅助。

序列号预测攻击：若 ISN 可预测，攻击者可伪造 TCP 包劫持连接。Linux 使用 MD5(四元组+时间+密钥) 保证不可预测性。

回绕不是 Bug 是 Feature：无符号整数自然溢出特性让内核无需做任何边界检查，代码极其简洁。

监控建议：使用 ss -tni 查看当前序列号状态（snd_nxt&#x2F;snd_una&#x2F;rcv_nxt），配合 netstat -s 查看 PAWS 丢包计数。


六、面试准备6.1 面试高频问答1. 初始序列号(ISN)生成算法// net/ipv4/tcp_ipv4.cu32 secure_tcp_sequence_number(__be32 saddr, __be32 daddr,                              __be16 sport, __be16 dport)&#123;    u32 hash[4];    u32 seq;        // RFC 6528: ISN生成算法    // 基于源IP、目标IP、源端口、目标端口和时间戳    hash[0] = (__force u32)saddr;    hash[1] = (__force u32)daddr;      hash[2] = ((__force u16)sport &lt;&lt; 16) + (__force u16)dport;    hash[3] = ktime_get_real_ns();        // MD5哈希生成伪随机数    md5_transform(hash, tcp_secret);        // 每4微秒递增1，防止序列号预测攻击    seq = hash[0];    seq += ktime_get_real_ns() &gt;&gt; 6; // 右移6位相当于除以64        return seq;&#125;

2. 连接建立时的序列号分配// 服务器端处理SYN请求int tcp_conn_request(struct request_sock_ops *rsk_ops,                    const struct tcp_request_sock_ops *af_ops,                    struct sock *sk, struct sk_buff *skb)&#123;    struct tcp_sock *tp = tcp_sk(sk);    struct request_sock *req;    u32 isn;        // 生成初始序列号    isn = af_ops-&gt;init_seq(skb);        // 创建连接请求结构    req = inet_reqsk_alloc(rsk_ops, sk, !want_cookie);    tcp_rsk(req)-&gt;snt_isn = isn;  // 保存服务器ISN        // SYN-ACK包的序列号就是这个ISN    return tcp_v4_send_synack(sk, dst, &amp;fl4, req, &amp;foc, !want_cookie);&#125;// 客户端发起连接int tcp_v4_connect(struct sock *sk, struct sockaddr *uaddr, int addr_len)&#123;    struct tcp_sock *tp = tcp_sk(sk);    __be32 daddr, nexthop;        // 生成客户端初始序列号    tp-&gt;write_seq = secure_tcp_sequence_number(inet-&gt;inet_saddr,                                              inet-&gt;inet_daddr,                                              inet-&gt;inet_sport,                                              usin-&gt;sin_port);    // 设置发送序列号    tp-&gt;snd_nxt = tp-&gt;write_seq;    tp-&gt;snd_una = tp-&gt;write_seq;        return tcp_connect(sk);&#125;

3. 序列号的安全考虑// RFC 6528 要求的安全特性static u32 tcp_init_seq_and_tsoff(const struct sk_buff *skb,                                  u32 *tsoff)&#123;    // 1. 基于连接四元组的唯一性    // 2. 时间相关性（防止重放攻击）    // 3. 不可预测性（防止序列号猜测攻击）    return secure_tcp_sequence_number(ip_hdr(skb)-&gt;saddr,                                     ip_hdr(skb)-&gt;daddr,                                     tcp_hdr(skb)-&gt;source,                                     tcp_hdr(skb)-&gt;dest) + *tsoff;&#125;

二、序列号数据类型和表示1. 序列号的数据类型// TCP序列号是32位无符号整数typedef u32 tcp_seq;struct tcp_sock &#123;    u32 snd_nxt;        // 下一个要发送的序列号    u32 snd_una;        // 最小的未确认序列号    u32 snd_up;         // 紧急指针    u32 write_seq;      // 应用层写入的序列号        u32 rcv_nxt;        // 期望接收的下一个序列号    u32 rcv_up;         // 接收紧急指针    u32 copied_seq;     // 用户已复制的序列号&#125;;

2. 序列号范围// 32位序列号的取值范围#define TCP_SEQ_MAX     0xFFFFFFFFU     // 4,294,967,295#define TCP_SEQ_MIN     0x00000000U     // 0// 序列号空间大小：4GB (2^32)// 理论最大传输：4GB数据后必须回绕

三、序列号回绕处理机制1. 回绕不是”重新初始化”// 错误理解：回绕时重新生成ISN ❌// 正确行为：继续递增，自然溢出 ✅void tcp_sequence_wrap_example() &#123;    u32 seq = 0xFFFFFFFE;  // 接近最大值        seq++;  // seq = 0xFFFFFFFF (最大值)    seq++;  // seq = 0x00000000 (自然回绕，不是重新初始化!)    seq++;  // seq = 0x00000001 (继续递增)        // 这是C语言无符号整数的自然溢出行为    // 内核不会检查&quot;负数&quot;，因为是无符号类型&#125;

2. 序列号比较函数// net/tcp.h - 处理回绕的序列号比较// 这些宏处理32位序列号的回绕情况// seq1是否在seq2之后（考虑回绕）static inline bool after(u32 seq1, u32 seq2)&#123;    return (s32)(seq1 - seq2) &gt; 0;&#125;// seq1是否在seq2之前（考虑回绕）static inline bool before(u32 seq1, u32 seq2)&#123;    return (s32)(seq1 - seq2) &lt; 0;&#125;// seq1是否在seq2之后或相等static inline bool after_eq(u32 seq1, u32 seq2)&#123;    return (s32)(seq1 - seq2) &gt;= 0;&#125;// seq1是否在seq2之前或相等static inline bool before_eq(u32 seq1, u32 seq2)&#123;    return (s32)(seq1 - seq2) &lt;= 0;&#125;

3. 回绕比较的数学原理// 示例：理解序列号比较的巧妙之处void sequence_comparison_examples() &#123;    // 正常情况    u32 seq1 = 1000, seq2 = 999;    printf(&quot;after(1000, 999) = %d\n&quot;, after(seq1, seq2)); // 1 (true)        // 回绕情况1：seq1回绕了，seq2没有    seq1 = 100;         // 已经回绕到小数值      seq2 = 0xFFFFFFF0;  // 还在大数值    printf(&quot;after(100, 0xFFFFFFF0) = %d\n&quot;, after(seq1, seq2)); // 1 (true)    // 因为 (s32)(100 - 0xFFFFFFF0) = (s32)(0x110) = 272 &gt; 0        // 回绕情况2：都回绕了    seq1 = 200, seq2 = 100;    printf(&quot;after(200, 100) = %d\n&quot;, after(seq1, seq2)); // 1 (true)        // 关键：这种比较方法假设序列号差值不会超过2^31    // 即任意两个有效序列号的差值 &lt; 2,147,483,648&#125;

四、实际的序列号处理1. 发送序列号更新// 发送数据时序列号的处理static bool tcp_write_xmit(struct sock *sk, unsigned int mss_now,                          int nonagle, int push_one, gfp_t gfp)&#123;    struct tcp_sock *tp = tcp_sk(sk);    struct sk_buff *skb;        while ((skb = tcp_send_head(sk))) &#123;        // 检查序列号是否在发送窗口内        if (after(TCP_SKB_CB(skb)-&gt;seq, tp-&gt;snd_una + tp-&gt;snd_wnd)) &#123;            // 超出发送窗口，停止发送            break;        &#125;                // 发送数据包        if (tcp_transmit_skb(sk, skb, 1, gfp))            break;                    // 更新下一个发送序列号（可能发生回绕）        tp-&gt;snd_nxt = TCP_SKB_CB(skb)-&gt;end_seq;  // 自然递增                // 检查回绕不影响逻辑        // 比如 snd_nxt 从 0xFFFFFFFF 变成 0x00000000        // 这是正常的，不需要特殊处理    &#125;        return sent_pkts;&#125;

2. 接收序列号验证// 接收数据时的序列号检查static void tcp_data_queue(struct sock *sk, struct sk_buff *skb)&#123;    struct tcp_sock *tp = tcp_sk(sk);    u32 seq = TCP_SKB_CB(skb)-&gt;seq;    u32 end_seq = TCP_SKB_CB(skb)-&gt;end_seq;        // 检查序列号是否在接收窗口内    if (before(seq, tp-&gt;rcv_nxt)) &#123;        // 重复数据或过时数据        goto drop;    &#125;        if (after_eq(seq, tp-&gt;rcv_nxt + tp-&gt;rcv_wnd)) &#123;        // 超出接收窗口的未来数据        goto drop;    &#125;        // 正常处理（按序或乱序）    if (seq == tp-&gt;rcv_nxt) &#123;        // 按序数据        __skb_queue_tail(&amp;sk-&gt;sk_receive_queue, skb);        tp-&gt;rcv_nxt = end_seq;  // 更新期望序列号（可能回绕）    &#125; else &#123;        // 乱序数据，加入乱序队列        tcp_data_queue_ofo(sk, skb);    &#125;&#125;

3. ACK序列号处理// 处理接收到的ACKstatic int tcp_ack(struct sock *sk, const struct sk_buff *skb, int flag)&#123;    struct tcp_sock *tp = tcp_sk(sk);    u32 ack = TCP_SKB_CB(skb)-&gt;ack_seq;    u32 prior_snd_una = tp-&gt;snd_una;        // 验证ACK序列号的有效性    if (before(ack, prior_snd_una)) &#123;        // 重复ACK或过时ACK        goto duplicate_ack;    &#125;        if (after(ack, tp-&gt;snd_nxt)) &#123;        // 未来ACK，不可能确认未发送的数据        goto invalid_ack;    &#125;        // 有效ACK，更新未确认序列号    tp-&gt;snd_una = ack;  // 可能涉及回绕        // 清理发送队列中已确认的数据    tcp_clean_rtx_queue(sk, prior_snd_una, ack);        return 1;&#125;

五、序列号回绕的边界情况1. PAWS（Protection Against Wrapped Sequences）// RFC 1323: 时间戳选项防止序列号回绕问题struct tcp_options_received &#123;    u8 tstamp_ok;       // 是否支持时间戳    u32 ts_recent;      // 最近的时间戳    unsigned long ts_recent_stamp; // 时间戳更新时间&#125;;// 使用时间戳验证回绕的序列号static bool tcp_paws_check(const struct tcp_options_received *rx_opt, int paws_win)&#123;    if (rx_opt-&gt;ts_recent_stamp &amp;&amp;        get_seconds() - rx_opt-&gt;ts_recent_stamp &gt; paws_win)        return false;            // 检查时间戳是否倒退（可能是回绕攻击）    return rx_opt-&gt;ts_recent &amp;&amp;            get_cycles() - rx_opt-&gt;ts_recent &lt; PAWS_24DAYS;&#125;

2. 序列号窗口限制// TCP限制序列号的有效范围#define TCP_MAX_WSCALE      14#define TCP_MAX_WINDOW      65535U// 最大可能的接收窗口#define MAX_TCP_WINDOW      (65535U &lt;&lt; TCP_MAX_WSCALE)  // ~1GB// 这确保了序列号差值不会超过2^31的限制// 从而保证序列号比较函数的正确性static inline bool tcp_sequence_wrap_safe(u32 start_seq, u32 end_seq)&#123;    // 确保序列号范围在安全区间内    return (end_seq - start_seq) &lt; (1U &lt;&lt; 31);&#125;

六、调试和监控1. 序列号状态监控// 通过 /proc/net/tcp 查看连接状态// sl  local_address rem_address   st tx_queue rx_queue tr tm-&gt;when retrnsmt   uid  timeout inode//  0: 0100007F:1F90 0100007F:DA02 01 00000000:00000000 00:00000000 00000000     0        0 10121// 或者使用 ss 命令// ss -i  # 显示详细的TCP信息，包括序列号状态

2. 内核调试// 启用TCP调试echo 1 &gt; /proc/sys/net/ipv4/tcp_debug// 或在代码中添加调试信息static void tcp_debug_sequence(struct sock *sk, u32 seq, const char *msg)&#123;    struct tcp_sock *tp = tcp_sk(sk);        printk(KERN_DEBUG &quot;TCP %s: seq=%u, snd_nxt=%u, snd_una=%u, rcv_nxt=%u\n&quot;,           msg, seq, tp-&gt;snd_nxt, tp-&gt;snd_una, tp-&gt;rcv_nxt);&#125;

七、关键要点总结1. 初始序列号特点
随机性: 基于时间和连接四元组生成，防止预测攻击
唯一性: 同一连接的ISN不会重复
安全性: 符合RFC 6528安全要求

2. 回绕处理要点
自然溢出: 32位无符号整数自然回绕到0，不重新初始化
比较算法: 使用有符号差值比较，处理回绕情况
安全限制: 序列号差值不超过2^31，配合PAWS防护

3. 常见误区澄清// ❌ 错误理解if (seq_num &lt; 0) &#123;  // 序列号是无符号数，不会小于0    reinitialize_sequence();&#125;// ❌ 错误理解  if (seq_num == 0xFFFFFFFF) &#123;    seq_num = generate_new_isn();  // 不需要重新生成ISN&#125;// ✅ 正确行为seq_num++;  // 自然递增，0xFFFFFFFF + 1 = 0x00000000

TCP序列号的设计体现了网络协议的精妙之处：通过数学技巧优雅地解决了回绕问题，既保证了协议的正确性，又避免了复杂的边界处理。
TCP序列号回绕后的变化就是自然递增，无缝衔接TCP序列号回绕后的变化机制一、序列号回绕的具体过程1. 数值变化演示// 32位无符号整数的自然溢出过程void sequence_wrap_demo() &#123;    u32 seq = 0xFFFFFFF0;  // 接近最大值        printf(&quot;序列号变化过程：\n&quot;);    for (int i = 0; i &lt; 20; i++) &#123;        printf(&quot;seq = 0x%08X (%u)\n&quot;, seq, seq);        seq++;  // 自然递增    &#125;&#125;// 输出结果：// seq = 0xFFFFFFF0 (4294967280)// seq = 0xFFFFFFF1 (4294967281)  // seq = 0xFFFFFFF2 (4294967282)// ...// seq = 0xFFFFFFFE (4294967294)// seq = 0xFFFFFFFF (4294967295)  &lt;- 最大值// seq = 0x00000000 (0)           &lt;- 回绕！// seq = 0x00000001 (1)           &lt;- 继续递增// seq = 0x00000002 (2)// seq = 0x00000003 (3)// ...

2. 实际TCP连接中的回绕// TCP连接状态在回绕前后的变化struct tcp_sequence_example &#123;    u32 snd_nxt;    // 下一个发送序列号    u32 snd_una;    // 未确认序列号    u32 rcv_nxt;    // 期望接收序列号&#125;;// 回绕前的状态struct tcp_sequence_example before_wrap = &#123;    .snd_nxt = 0xFFFFFFF0,  // 即将发送 0xFFFFFFF0    .snd_una = 0xFFFFFE00,  // 0xFFFFFE00 还未确认    .rcv_nxt = 0xFFFFFF00   // 期望接收 0xFFFFFF00&#125;;// 发送几个数据包后...struct tcp_sequence_example after_wrap = &#123;    .snd_nxt = 0x00000010,  // 已经回绕，现在要发送 0x00000010    .snd_una = 0xFFFFFF00,  // 回绕前的数据还在等待确认    .rcv_nxt = 0x00000008   // 期望接收序列号也回绕了&#125;;

二、回绕过程中的具体操作1. 发送序列号的连续性// TCP发送数据时的序列号分配int tcp_sendmsg_example(struct sock *sk, const char *data, int len)&#123;    struct tcp_sock *tp = tcp_sk(sk);    u32 current_seq = tp-&gt;write_seq;        // 场景：当前序列号接近最大值    printf(&quot;发送前 write_seq = 0x%08X\n&quot;, current_seq);        // 假设要发送1000字节数据，分成几个包    for (int i = 0; i &lt; len; i += 500) &#123;        int seg_len = min(500, len - i);                // 创建TCP段        struct sk_buff *skb = alloc_skb(seg_len, GFP_KERNEL);        TCP_SKB_CB(skb)-&gt;seq = current_seq;        TCP_SKB_CB(skb)-&gt;end_seq = current_seq + seg_len;                printf(&quot;TCP段：seq=0x%08X, end_seq=0x%08X, len=%d\n&quot;,               TCP_SKB_CB(skb)-&gt;seq, TCP_SKB_CB(skb)-&gt;end_seq, seg_len);                // 序列号递增（可能发生回绕）        current_seq += seg_len;    &#125;        tp-&gt;write_seq = current_seq;    printf(&quot;发送后 write_seq = 0x%08X\n&quot;, tp-&gt;write_seq);&#125;// 输出示例（发送1000字节，序列号从0xFFFFFF00开始）：// 发送前 write_seq = 0xFFFFFF00// TCP段：seq=0xFFFFFF00, end_seq=0xFFFFFF00+500=0x000000F4, len=500  &lt;- 回绕！// TCP段：seq=0x000000F4, end_seq=0x000000F4+500=0x000002E8, len=500// 发送后 write_seq = 0x000002E8

2. 接收序列号的处理// 接收端处理回绕的序列号void tcp_data_queue_wrap_example(struct sock *sk, struct sk_buff *skb)&#123;    struct tcp_sock *tp = tcp_sk(sk);    u32 seq = TCP_SKB_CB(skb)-&gt;seq;    u32 end_seq = TCP_SKB_CB(skb)-&gt;end_seq;        printf(&quot;接收数据包：seq=0x%08X, end_seq=0x%08X\n&quot;, seq, end_seq);    printf(&quot;当前期望：rcv_nxt=0x%08X\n&quot;, tp-&gt;rcv_nxt);        // 使用after/before函数处理回绕比较    if (seq == tp-&gt;rcv_nxt) &#123;        // 按序到达        printf(&quot;按序数据，更新 rcv_nxt: 0x%08X -&gt; 0x%08X\n&quot;,                tp-&gt;rcv_nxt, end_seq);        tp-&gt;rcv_nxt = end_seq;  // 可能从大数跳到小数    &#125;    else if (after(seq, tp-&gt;rcv_nxt)) &#123;        // 乱序到达（序列号比期望的大）        printf(&quot;乱序数据，放入乱序队列\n&quot;);    &#125;    else &#123;        // 重复或过时数据        printf(&quot;重复/过时数据，丢弃\n&quot;);    &#125;&#125;

三、序列号比较在回绕中的应用1. 关键比较函数的工作原理// 序列号比较函数如何处理回绕void sequence_comparison_detailed() &#123;    // 测试用例1：正常情况（无回绕）    u32 seq1 = 1000, seq2 = 999;    printf(&quot;after(1000, 999) = %d\n&quot;, after(seq1, seq2));    // (s32)(1000 - 999) = 1 &gt; 0，返回true        // 测试用例2：seq1回绕，seq2未回绕    seq1 = 100;           // 已经回绕到小值    seq2 = 0xFFFFFF00;    // 还是大值    printf(&quot;after(100, 0xFFFFFF00) = %d\n&quot;, after(seq1, seq2));    // (s32)(100 - 0xFFFFFF00) = (s32)(0xFFFFFF00 + 100) = (s32)(0x100) = 256 &gt; 0    // 返回true，正确识别100在时间上晚于0xFFFFFF00        // 测试用例3：两个都是回绕后的小值    seq1 = 200, seq2 = 100;    printf(&quot;after(200, 100) = %d\n&quot;, after(seq1, seq2));    // (s32)(200 - 100) = 100 &gt; 0，返回true        // 测试用例4：边界情况    seq1 = 0x80000001;  // 刚超过2^31    seq2 = 0x7FFFFFFF;  // 2^31 - 1    printf(&quot;after(0x80000001, 0x7FFFFFFF) = %d\n&quot;, after(seq1, seq2));    // (s32)(0x80000001 - 0x7FFFFFFF) = (s32)(2) = 2 &gt; 0，返回true&#125;

2. 窗口检查中的回绕处理// TCP接收窗口检查bool tcp_sequence_in_window(u32 seq, u32 rcv_nxt, u32 rcv_wnd)&#123;    // 检查序列号是否在接收窗口内    // 窗口范围：[rcv_nxt, rcv_nxt + rcv_wnd)        if (before(seq, rcv_nxt)) &#123;        // 序列号在窗口左边界之前        return false;    &#125;        if (after_eq(seq, rcv_nxt + rcv_wnd)) &#123;        // 序列号在窗口右边界之后        // 注意：rcv_nxt + rcv_wnd 也可能发生回绕        return false;    &#125;        return true;&#125;// 回绕窗口检查示例void window_wrap_example() &#123;    u32 rcv_nxt = 0xFFFFFF00;  // 接收窗口起始    u32 rcv_wnd = 65536;       // 窗口大小64KB        // 窗口范围：[0xFFFFFF00, 0xFFFFFF00 + 65536]    // 由于回绕：[0xFFFFFF00, 0x0000FF00]        printf(&quot;窗口：[0x%08X, 0x%08X]\n&quot;, rcv_nxt, rcv_nxt + rcv_wnd);    // 输出：窗口：[0xFFFFFF00, 0x0000FF00]        // 测试不同序列号    u32 test_seqs[] = &#123;0xFFFFFF50, 0x00000050, 0x0000FF50&#125;;        for (int i = 0; i &lt; 3; i++) &#123;        bool in_window = tcp_sequence_in_window(test_seqs[i], rcv_nxt, rcv_wnd);        printf(&quot;seq=0x%08X 在窗口内：%s\n&quot;,                test_seqs[i], in_window ? &quot;是&quot; : &quot;否&quot;);    &#125;&#125;

四、ACK确认中的回绕处理1. ACK处理的序列号更新// 处理ACK确认时的序列号回绕int tcp_ack_wrap_example(struct sock *sk, u32 ack_seq)&#123;    struct tcp_sock *tp = tcp_sk(sk);    u32 prior_snd_una = tp-&gt;snd_una;        printf(&quot;收到ACK：ack_seq=0x%08X, 当前snd_una=0x%08X\n&quot;,            ack_seq, prior_snd_una);        // 验证ACK的有效性（处理回绕）    if (after(ack_seq, tp-&gt;snd_nxt)) &#123;        printf(&quot;未来ACK，拒绝：ack_seq &gt; snd_nxt\n&quot;);        return -1;    &#125;        if (before_eq(ack_seq, prior_snd_una)) &#123;        printf(&quot;重复ACK：ack_seq &lt;= snd_una\n&quot;);        return 0;  // 重复ACK，可能用于快速重传    &#125;        // 有效的新确认    tp-&gt;snd_una = ack_seq;    printf(&quot;更新snd_una：0x%08X -&gt; 0x%08X\n&quot;, prior_snd_una, ack_seq);        // 计算新确认的字节数（处理回绕）    u32 acked_bytes = ack_seq - prior_snd_una;    printf(&quot;新确认字节数：%u (可能经过回绕计算)\n&quot;, acked_bytes);        return acked_bytes;&#125;// 回绕ACK示例void ack_wrap_demo() &#123;    struct tcp_sock tp;    tp.snd_una = 0xFFFFFF00;  // 未确认起始点    tp.snd_nxt = 0x00000100;  // 已发送到这里（跨越回绕）        // 接收到确认回绕前数据的ACK    tcp_ack_wrap_example((struct sock*)&amp;tp, 0xFFFFFFFF);    // 输出：更新snd_una：0xFFFFFF00 -&gt; 0xFFFFFFFF    // 新确认字节数：255        // 接收到确认回绕后数据的ACK      tcp_ack_wrap_example((struct sock*)&amp;tp, 0x00000080);    // 输出：更新snd_una：0xFFFFFFFF -&gt; 0x00000080    // 新确认字节数：129 (0x00000080 - 0xFFFFFFFF = 129)&#125;

2. 发送队列清理中的回绕// 清理已确认数据包时的序列号处理void tcp_clean_rtx_queue_wrap(struct sock *sk, u32 ack_seq)&#123;    struct sk_buff *skb, *next;    u32 packets_acked = 0;        // 遍历发送队列，清理已确认的数据包    skb_queue_walk_safe(&amp;sk-&gt;sk_write_queue, skb, next) &#123;        u32 scb_seq = TCP_SKB_CB(skb)-&gt;seq;        u32 end_seq = TCP_SKB_CB(skb)-&gt;end_seq;                printf(&quot;检查包：seq=0x%08X, end_seq=0x%08X, ack=0x%08X\n&quot;,               scb_seq, end_seq, ack_seq);                if (after(end_seq, ack_seq)) &#123;            // 这个包的结束序列号大于ACK，说明未完全确认            if (after(scb_seq, ack_seq)) &#123;                // 包的开始都大于ACK，后续包都不会被确认                break;            &#125; else &#123;                // 部分确认，需要分割（实际实现更复杂）                printf(&quot;部分确认，需要分割包\n&quot;);                break;            &#125;        &#125;                // 完全确认的包，可以删除        printf(&quot;删除已确认包：seq=0x%08X, end_seq=0x%08X\n&quot;, scb_seq, end_seq);        __skb_unlink(skb, &amp;sk-&gt;sk_write_queue);        kfree_skb(skb);        packets_acked++;    &#125;        printf(&quot;总共确认了 %u 个数据包\n&quot;, packets_acked);&#125;

五、回绕时的性能考虑1. 时间戳选项（PAWS）// RFC 1323：使用时间戳防止回绕序列号的歧义struct tcp_options_received &#123;    u8  tstamp_ok;      // 是否启用时间戳    u32 ts_recent;      // 对方最近的时间戳    u32 ts_ecr;         // 回显的时间戳&#125;;// 回绕时的时间戳检查bool tcp_paws_discard(const struct sock *sk, const struct sk_buff *skb)&#123;    const struct tcp_sock *tp = tcp_sk(sk);        // 如果序列号看起来是&quot;旧的&quot;，但时间戳是&quot;新的&quot;    // 说明这是回绕后的新数据，不应该丢弃    if (tp-&gt;rx_opt.ts_recent &amp;&amp;         get_seconds() - tp-&gt;rx_opt.ts_recent_stamp &lt; TCP_PAWS_24DAYS &amp;&amp;        TCP_SKB_CB(skb)-&gt;when &lt; tp-&gt;rx_opt.ts_recent) &#123;        return true;  // 丢弃过时数据    &#125;        return false;&#125;

2. 大带宽环境下的回绕频率// 计算序列号回绕频率void sequence_wrap_frequency() &#123;    u32 seq_space = 0xFFFFFFFFU + 1;  // 4GB序列号空间        // 不同带宽下的回绕时间    struct &#123;        const char* name;        u64 bps;  // bits per second    &#125; bandwidths[] = &#123;        &#123;&quot;1Gbps&quot;,   1000000000ULL&#125;,        &#123;&quot;10Gbps&quot;, 10000000000ULL&#125;,        &#123;&quot;40Gbps&quot;, 40000000000ULL&#125;,        &#123;&quot;100Gbps&quot;,100000000000ULL&#125;    &#125;;        printf(&quot;不同带宽下序列号回绕时间：\n&quot;);    for (int i = 0; i &lt; 4; i++) &#123;        // 计算发送4GB数据需要的时间        u64 bits = (u64)seq_space * 8;  // 转换为bit        u64 seconds = bits / bandwidths[i].bps;                printf(&quot;%s: %llu秒 (%.1f分钟)\n&quot;,                bandwidths[i].name, seconds, seconds / 60.0);    &#125;&#125;// 输出示例：// 1Gbps: 34秒 (0.6分钟)// 10Gbps: 3秒 (0.1分钟) // 40Gbps: 1秒 (0.0分钟)// 100Gbps: 0秒 (0.0分钟)

六、调试回绕问题1. 序列号状态跟踪// 调试宏：跟踪序列号变化#ifdef TCP_DEBUG_SEQUENCE#define tcp_seq_debug(sk, msg, seq) do &#123; \    struct tcp_sock *tp = tcp_sk(sk); \    printk(KERN_DEBUG &quot;TCP SEQ %s: seq=0x%08X, snd_nxt=0x%08X, &quot; \           &quot;snd_una=0x%08X, rcv_nxt=0x%08X\n&quot;, \           msg, seq, tp-&gt;snd_nxt, tp-&gt;snd_una, tp-&gt;rcv_nxt); \&#125; while(0)#else#define tcp_seq_debug(sk, msg, seq) do &#123; &#125; while(0)#endif// 在关键位置插入调试void tcp_transmit_skb_debug(struct sock *sk, struct sk_buff *skb)&#123;    tcp_seq_debug(sk, &quot;发送前&quot;, TCP_SKB_CB(skb)-&gt;seq);        // 实际发送...        tcp_seq_debug(sk, &quot;发送后&quot;, TCP_SKB_CB(skb)-&gt;end_seq);&#125;

2. 用户空间监控# 使用ss命令监控TCP状态ss -i -t -n | grep ESTAB# 输出示例（注意Recv-Q和Send-Q的序列号信息）:# ESTAB  0  0  192.168.1.100:22  192.168.1.200:54321#        cubic wscale:7,7 rto:201 rtt:0.5/0.25 send 1680.0Mbps #        lastsnd:0 lastrcv:0 lastack:0 pacing_rate 3360.0Mbps# 或者查看详细的TCP统计cat /proc/net/tcp# 显示连接的发送和接收队列状态

七、总结回绕后序列号的变化特点：
连续性：序列号从0xFFFFFFFF自然溢出到0x00000000，保持连续
透明性：应用层无需感知回绕，TCP协议栈自动处理
一致性：所有序列号相关操作（比较、窗口检查、确认）都正确工作
效率性：无需额外的边界检查，依靠数学技巧处理

关键设计原则：
无符号算术：利用C语言无符号整数的自然溢出特性
差值比较：通过有符号差值判断序列号的相对位置
窗口限制：确保有效序列号范围在2^31以内
时间戳辅助：在高速网络中用PAWS防止歧义

这种设计让TCP可以在32位序列号空间内”无限”传输数据，是网络协议设计的经典范例。
六、面试准备6.1 面试高频问答Q1：TCP 序列号为什么是 32 位？
A：32 位提供约 4GB 的序列号空间。结合窗口限制（2^31 范围），足够区分新旧数据。高速网络中结合时间戳 PAWS 进一步防回绕歧义。
Q2：PAWS (Protection Against Wrapped Sequences) 的原理？
A：每个 TCP 段携带时间戳选项，接收方只接受时间戳大于最近记录值的包。即使序列号回绕到相同值，时间戳也足以区分新旧数据。
Q3：ISN 为什么需要随机化？
A：防止攻击者猜测序列号劫持连接（TCP Sequence Prediction Attack）。RFC 6528 定义了基于 MD5 哈希的 ISN 生成算法。
Q4：序列号回绕对高速网络有什么影响？
A：10Gbps+ 网络中，32 位序列号在约 3.4 秒内耗尽。PAWS 通过时间戳辅助解决，但在超高速网络（100Gbps+）TCP 时间戳粒度可能需要调整。
Q5：接收窗口和序列号的关系？
A：接收方通告窗口大小，发送方保证发送数据不超过 [snd_una, snd_una + rcv_wnd)。窗口限制了序列号有效范围，也是回绕安全的基础。
Q6：有了 PAWS 还需要序列号回绕保护吗？
A：需要。PAWS 是可选字段（非所有实现都启用），序列号本身的回绕保护（窗口限制在有符号 2^31 内）是 TCP 的基本保证。
6.2 陷阱与反问陷阱1：忽略 PAWS 导致高速网络回绕歧义 → 数据损坏陷阱2：ISN 固定 → 安全漏洞，连接可被劫持陷阱3：时间戳选项不兼容 → 某些老旧设备不支持 PAWS
反问：在 100Gbps 网络中 TCP 32 位序列号多久回绕一次？答案：32 位 &#x3D; 4GB，100Gbps ≈ 12.5GB&#x2F;s，回绕时间 &#x3D; 4GB &#x2F; 12.5GB&#x2F;s ≈ 0.32 秒。这就是为什么 TCP 时间戳选项在高带宽场景中至关重要。
6.3 一句话答案
ISN：随机化的初始序列号，防止连接劫持
序列号空间：32 位 &#x3D; 4GB，循环回绕使用
PAWS：基于时间戳的回绕保护，区分新旧数据
窗口限制：发送窗口 &lt; 2^31 字节，保证序列号比较有效性
时间戳选项：TCP 扩展选项，辅助 RTTM 和 PAWS
回绕检测：通过有符号差值 after(seq1, seq2) 判断相对位置

epoll
适用范围：Linux I&#x2F;O多路复用、epoll 事件驱动机制、epoll_create&#x2F;epoll_ctl&#x2F;epoll_wait 系统调用、LT与ET触发模式、eventpoll&#x2F;epitem 内核源码实现

一、核心概念
定义：epoll 是 Linux 内核提供的可扩展 I&#x2F;O 多路复用机制，用于高效监视大量文件描述符上的 I&#x2F;O 事件。与 select&#x2F;poll 的轮询遍历不同，epoll 采用事件驱动+回调机制，通过红黑树管理监视集、就绪链表交付激活事件，实现 O(1) 就绪获取
关键词：eventpoll、epitem、红黑树(rbr)、就绪链表(rdllist)、ep_poll_callback、水平触发(LT)、边缘触发(ET)、EPOLLONESHOT、EPOLLEXCLUSIVE、ovflist
适用场景&#x2F;边界：
高并发网络服务器（C10K&#x2F;C100K 的经典解决方案）
需要同时监视大量 socket fd 且只有少数活跃的场景
边界：仅 Linux 平台可用（BSD 用 kqueue，Windows 用 IOCP）；主要优化网络 socket，对普通文件（磁盘文件总是就绪）支持有限



二、详细解析（≥200字）epoll 并不是对 select 和 poll 的缝缝补补，而是全新的架构，但是其底层仍然是文件系统的 poll 机制和等待队列。
select 和 poll 是无状态的，每次调用都需要将需要监视的 fd 从用户空间拷贝到内核，完成时将整个数据再次拷贝回用户空间，拷回的并不是就绪的 fd，而是所有的 fd，用户需要遍历才能获取哪个 fd 就绪了。
epoll 是有状态的，每个 epoll 在内核中都记录了需要监视的 fd，调用 epoll_ctl(2) 注册事件的时候将相关数据拷入内核，以后调用 epoll_wait(2) 不会像 select(2) 或 poll(2) 那样，每次都从用户空间拷贝数据到内核空间，并且 epoll_wait(2) 返回的是就绪的 fd。
#include &lt;sys/epoll.h&gt;int epoll_create(int size);int epoll_ctl(int epfd, int op, int fd, struct epoll_event *event);int epoll_wait(int epfd, struct epoll_event *events,                int maxevents, int timeout);/// include/uapi/linux/eventpoll.htypedef union epoll_data&#123;    void *ptr;    int fd;    uint32_t u32;    uint64_t u64;&#125; epoll_data_t;struct epoll_event&#123;    uint32_t events;      /* IO 事件 */    epoll_data_t data;    /* User data variable */&#125; __EPOLL_PACKED;

epoll_create() 做了什么如前文所说，epoll 是有状态的，epoll(7) 在内核中会保存需要监视事件（文件和期望的就绪状态），可以通过 epoll_ctl(2) 来完成监听事件的添加、修改和移除。所以需要某种方法标识每一个 epoll 实例，以区分不同的 epoll 实例。
按照 Linux 一切皆文件的思想，epoll 是借助虚拟文件系统，通过文件描述符来标识每一个 epoll 实例。epoll 使用 eventpoll 顶层结果管理所有的事件。
eventpoll一切皆文件，创建 eventpoll 对象会绑定一个匿名文件的 file 对象。我们可以像操作文件一样操作 eventpoll 对象。struct file 结构中 private_data 指向的是文件系统私有数据，eventpoll 就是挂到 private_data 指针上。其总体布局如下所示：

eventpoll 结构几个成员简单备注一下

1）wq：等待队列，调用 epoll_wait() 的进程会被挂在上面；
2）poll_wait：epoll 文件的等待队列。epfd 也可以注册到其他 epoll 中；
3）rdllist：就绪队列，epoll_wait() 将 rdllist 链表上就绪事件拷贝到用户空间返回；
4）rbr：红黑树根节点，所有 epitem 都在一棵红黑树上；
5）ovflist：当 rdllist 正在使用时（占用 lock），就绪的事件添加到 ovflist 链表上；

/// fs/eventpoll.cstruct eventpoll &#123;    struct mutex mtx;    /* epoll_wait 的等待队列 */    wait_queue_head_t wq;    /* epoll 的等待队列 */    wait_queue_head_t poll_wait;    /* 就绪事件链表 */    struct list_head rdllist;    /* 保护 rdllist and ovflist */    rwlock_t lock;    /* 红黑树根节点，管理所有 fd */    struct rb_root_cached rbr;    /* 备用就绪队列，在 fdllist 占用 lock 时被使用 */    struct epitem *ovflist;    /* wakeup_source used when ep_scan_ready_list is running */    struct wakeup_source *ws;    /* The user that created the eventpoll descriptor */    struct user_struct *user;    /* eventpoll 归属的文件 */    struct file *file;    /* used to optimize loop detection check */    u64 gen;    #ifdef CONFIG_NET_RX_BUSY_POLL    /* used to track busy poll napi_id */    unsigned int napi_id;    #endif    #ifdef CONFIG_DEBUG_LOCK_ALLOC    /* tracks wakeup nests for lockdep validation */    u8 nests;    #endif&#125;;

总结一下：eventpoll 结构体管理所有的监视事件：

1）所有监视事件用红黑树串联起来
2）一切皆文件，创建 eventpoll 对象会绑定一个匿名文件的 file 对象。我们可以像操作文件一样操作 eventpoll 对象。

ep_alloc() 用于申请一个 eventpoll 对象，ovflist 被初始化为 EP_UNACTIVE_PTR，当 rdllist 在使用时，ovflist 被修改为 NULL，开始暂时接受就绪事件。
/// fs/eventpoll.cstatic int ep_alloc(struct eventpoll **pep)&#123;    int error;    struct user_struct *user;    struct eventpoll *ep;    user = get_current_user();    error = -ENOMEM;    ep = kzalloc(sizeof(*ep), GFP_KERNEL); // 申请 epitem 实例    if (unlikely(!ep))        goto free_uid;    mutex_init(&amp;ep-&gt;mtx);    rwlock_init(&amp;ep-&gt;lock);    init_waitqueue_head(&amp;ep-&gt;wq);    init_waitqueue_head(&amp;ep-&gt;poll_wait);    INIT_LIST_HEAD(&amp;ep-&gt;rdllist);    ep-&gt;rbr = RB_ROOT_CACHED;    ep-&gt;ovflist = EP_UNACTIVE_PTR; // 未使用    ep-&gt;user = user;    *pep = ep;    return 0;    free_uid:    free_uid(user);    return error;&#125;

epitem向 epoll 注册的 fd，epoll 都使用 epitem 表示。epoll 中所有的 epitem 用红黑树串联起来。

rbn 是红黑树节点，挂在红黑树上
rdllink 是就绪队列，所有就绪的 epitem 连接成链表
pwqlist 连接 eppoll_entry

/// fs/eventpoll.cstruct epitem &#123;    union &#123;        struct rb_node rbn; // 挂到红黑树上        struct rcu_head rcu; // 释放 epitem 时使用    &#125;;    struct list_head rdllink; // 挂到就绪队列     struct epitem *next; // 挂到备用队列    struct epoll_filefd ffd; // 包含 file 和 fd    /* Number of active wait queue attached to poll operations */    int nwait;    /* List containing poll wait queues */    struct list_head pwqlist;    struct eventpoll *ep; // 所属 eventpoll    /* List header used to link this item to the &quot;struct file&quot; items list */    struct list_head fllink; // 链接所有 file    /* wakeup_source used when EPOLLWAKEUP is set */    struct wakeup_source __rcu *ws;    struct epoll_event event; // 监视事件&#125;;

epoll_create()可以看到 size 参数没有任何作用，只要大于 0 就行。
/// fs/eventpoll.cSYSCALL_DEFINE1(epoll_create, int, size)&#123;    if (size &lt;= 0)        return -EINVAL;    return do_epoll_create(0);&#125;

do_epoll_create() 函数做三件事：

1）调用 ep_alloc() 申请一个 eventpoll 对象；
2）调用 get_unused_fd_flags() 获取一个 fd；
3）调用 anon_inode_getfile() 从匿名文件系统申请一个 file 对象，filp-&gt;private_data 指向 eventpoll 对象；另外文件系统 file_operations 是 eventpoll_fops；


/// fs/eventpoll.cstatic int do_epoll_create(int flags)&#123;    int error, fd;    struct eventpoll *ep = NULL;    struct file *file;    // ...    error = ep_alloc(&amp;ep); // 申请一个 eventpoll 对象    if (error &lt; 0)        return error;    // 申请一个未使用的 fd    fd = get_unused_fd_flags(O_RDWR | (flags &amp; O_CLOEXEC));    if (fd &lt; 0) &#123;        error = fd;        goto out_free_ep;    &#125;    // 匿名文件，文件操作是 eventpoll_fops    file = anon_inode_getfile(&quot;[eventpoll]&quot;, &amp;eventpoll_fops, ep,                              O_RDWR | (flags &amp; O_CLOEXEC));    if (IS_ERR(file)) &#123;        error = PTR_ERR(file);        goto out_free_fd;    &#125;    ep-&gt;file = file; // 绑定 file 实例    fd_install(fd, file);    return fd;    out_free_fd:    put_unused_fd(fd);    out_free_ep:    ep_free(ep);    return error;&#125;

anon_inode_getfile() 函数不会申请 inode，而是使用匿名文件统一的 inode。然后调用 alloc_file_pseudo() 申请一个 file 对象，private_data 指向 eventpoll 对象。
eventpoll_fops.poll 指向的是 ep_eventpoll_poll 函数。
/// fs/eventpoll.cstatic const struct file_operations eventpoll_fops = &#123;    #ifdef CONFIG_PROC_FS    .show_fdinfo	= ep_show_fdinfo,    #endif    .release	= ep_eventpoll_release,    .poll		= ep_eventpoll_poll,    .llseek		= noop_llseek,&#125;;

根据 f_op 是否执行 eventpoll_fops，可以判断 file 是否是被 epoll 绑定。
/// fs/eventpoll.cstatic inline int is_file_epoll(struct file *f)&#123;    return f-&gt;f_op == &amp;eventpoll_fops;&#125;

epoll_create(2) 系统调用完成了 fd、file 和 eventpoll 三个对象之间的关联，并将 fd 返回给用户态应用程序。每一个 fd 都会对应一个 eventpoll 对象，用户通过 fd 可以将需要监视的目标事件添加到 eventpoll 中。
epoll 为什么高效前文讲到，epoll_wait 返回的是就绪的 fd，而不是全部的监视 fd，减少了用户遍历的时间。
另外一点，不需要像 select 和 poll 那样需要遍历整个 fd 集合，核查是否就绪才将其移动到就绪队列。epoll 不需要遍历所有监视的 fd，就能获取就绪的 fd。目标文件就绪事件发生后，就将对应的 epitem 挂到就绪队列上了，epoll 直接检查就绪队列就可以了，所以 epoll 很高效。这是如何做到的呢？
我们提前看看向 epoll 注册 fd 时，调用 vfs_poll() 获取文件状态时，回调函数是如何设置的。
/// fd/eventpoll.cstatic int ep_insert(struct eventpoll *ep, const struct epoll_event *event,                     struct file *tfile, int fd, int full_check)&#123;    // ...    struct epitem *epi;    struct ep_pqueue epq;    // ...    epq.epi = epi;    // 设置 poll 机制的回调函数    init_poll_funcptr(&amp;epq.pt, ep_ptable_queue_proc);    // 调用 vs_poll    revents = ep_item_poll(epi, &amp;epq.pt, 1);    // ...&#125;

ep_pqueue 就是封装了 poll_table 和 epitem，这样可以很好地通过 pt 找到对应的 epitem
/// fs/eventpoll.cstruct ep_pqueue &#123;    poll_table pt;    struct epitem *epi;&#125;;

ep_item_poll()因为 epoll 实例也可以被添加到其他 epoll 实例中（但是不能添加到自己），所以 ep_item_poll 需要区分普通文件和 epoll 文件。

对于普通文件，调用 vfs_poll 使用其 pull 机制
对于 epfd 文件，直接调用 poll_wait() 函数，然后遍历目标 epoll 实例的 rdllist

首先查看普通文件的操作，vfs_poll() 函数会调用 file-&gt;f_op-&gt;poll 指向的函数。在 poll 机制的文章中，分析到最后回调用 poll_table 设置的回调函数，在这里，也就是 ep_ptable_queue_proc() 函数。
如果是 epoll 文件，不使用 file_operation::poll 指向的函数，直接使用 poll_wait() 函数，然后检查就绪队列是否有就绪事件。
/// fs/eventpoll.cstatic __poll_t ep_item_poll(const struct epitem *epi, poll_table *pt,                             int depth)&#123;    struct eventpoll *ep;    bool locked;    pt-&gt;_key = epi-&gt;event.events; // 等待事件    if (!is_file_epoll(epi-&gt;ffd.file)) // 非 epoll 文件，走 vfs        return vfs_poll(epi-&gt;ffd.file, pt) &amp; epi-&gt;event.events;    // epoll 文件，调用 poll_wait    // 将 epi 挂到目标 epoll 实例的 poll_wait 等待队列上    ep = epi-&gt;ffd.file-&gt;private_data;    poll_wait(epi-&gt;ffd.file, &amp;ep-&gt;poll_wait, pt);    locked = pt &amp;&amp; (pt-&gt;_qproc == ep_ptable_queue_proc);    // 检查目标 epoll 实例是否有就绪事件    return ep_scan_ready_list(epi-&gt;ffd.file-&gt;private_data,                              ep_read_events_proc, &amp;depth, depth,                              locked) &amp; epi-&gt;event.events;&#125;

ep_ptable_queue_proc()ep_ptable_queue_proc() 将一个 eppoll_entry 对象挂到某个文件（监视的文件）的等待队列上，并且设置就绪事件发生时，调用的函数是 ep_poll_callback() 函数。
这里不太明白 pwqlist 作用，难道不是只有一个 eppoll_entry 吗？
/// fs/eventpoll.cstatic void ep_ptable_queue_proc(struct file *file, wait_queue_head_t *whead,                                 poll_table *pt)&#123;    struct epitem *epi = ep_item_from_epqueue(pt);    struct eppoll_entry *pwq;    if (epi-&gt;nwait &gt;= 0 &amp;&amp; (pwq = kmem_cache_alloc(pwq_cache, GFP_KERNEL))) &#123;        init_waitqueue_func_entry(&amp;pwq-&gt;wait, ep_poll_callback);        pwq-&gt;whead = whead;        pwq-&gt;base = epi;        if (epi-&gt;event.events &amp; EPOLLEXCLUSIVE)            add_wait_queue_exclusive(whead, &amp;pwq-&gt;wait);        else            add_wait_queue(whead, &amp;pwq-&gt;wait);        list_add_tail(&amp;pwq-&gt;llink, &amp;epi-&gt;pwqlist);        epi-&gt;nwait++;    &#125; else &#123;        /* We have to signal that an error occurred */        epi-&gt;nwait = -1;    &#125;&#125;

pt-&gt;_qproc 只有在 ep_insert() 函数中被赋值，指向 ep_ptable_queue_proc() 函数，其他时候调用时，其为 NULL。当 _qproc 为 NULL 时，poll_wait() 只获取文件事件状态。
eppoll_entry 也是为了从 wait 找到对应的 epitem
/// fs/eventpoll.cstruct eppoll_entry &#123;    struct list_head llink; // 连接 epitem::pwdlist    struct epitem *base; // 所属的 epitem    wait_queue_entry_t wait; // 挂到等待队列上    wait_queue_head_t *whead; // 挂在哪个等待队列上&#125;;

ep_poll_callback()回调函数 ep_poll_callback() 在事件就绪后，将对应的 epitem 对象添加到 eventpoll 的就绪链表中，然后唤醒阻塞的进程，包括阻塞在 epoll_wait() 系统调用的进程，以及监视 epollfd 的其他 epoll 实例。
/// fs/eventpoll.cstatic int ep_poll_callback(wait_queue_entry_t *wait, unsigned mode, int sync, void *key)&#123;    int pwake = 0;    struct epitem *epi = ep_item_from_wait(wait);    struct eventpoll *ep = epi-&gt;ep;    __poll_t pollflags = key_to_poll(key); // 发生的事件    unsigned long flags;    int ewake = 0;    read_lock_irqsave(&amp;ep-&gt;lock, flags);    ep_set_busy_poll_napi_id(epi);    if (!(epi-&gt;event.events &amp; ~EP_PRIVATE_BITS)) // 没有事件，返回        goto out_unlock;    // 不是监视的事件，返回    if (pollflags &amp;&amp; !(pollflags &amp; epi-&gt;event.events))        goto out_unlock;    // 获取备用队列 ovflist 的状态，如果被启用，就使用 ovflist    if (READ_ONCE(ep-&gt;ovflist) != EP_UNACTIVE_PTR) &#123;        if (chain_epi_lockless(epi)) // 添加到 ovflist 链表（无锁操作）            ep_pm_stay_awake_rcu(epi);    &#125; else if (!ep_is_linked(epi)) &#123; // 添加到 rdllink（无锁操作）        if (list_add_tail_lockless(&amp;epi-&gt;rdllink, &amp;ep-&gt;rdllist))            ep_pm_stay_awake_rcu(epi);    &#125;    // 唤醒调用 epoll_wiat() 被阻塞的进程    if (waitqueue_active(&amp;ep-&gt;wq)) &#123; // 有阻塞的进程        if ((epi-&gt;event.events &amp; EPOLLEXCLUSIVE) &amp;&amp;            !(pollflags &amp; POLLFREE)) &#123;            switch (pollflags &amp; EPOLLINOUT_BITS) &#123;                case EPOLLIN:                    if (epi-&gt;event.events &amp; EPOLLIN)                        ewake = 1;                    break;                case EPOLLOUT:                    if (epi-&gt;event.events &amp; EPOLLOUT)                        ewake = 1;                    break;                case 0:                    ewake = 1;                    break;            &#125;        &#125;        wake_up(&amp;ep-&gt;wq); // 唤醒    &#125;    // 唤醒监视 epoll 的其他 epoll 实例    if (waitqueue_active(&amp;ep-&gt;poll_wait)) // 有阻塞的进程        pwake++;    out_unlock:    read_unlock_irqrestore(&amp;ep-&gt;lock, flags);    /* We have to call this outside the lock */    if (pwake)        ep_poll_safewake(ep, epi); // 唤醒    if (!(epi-&gt;event.events &amp; EPOLLEXCLUSIVE))        ewake = 1;    if (pollflags &amp; POLLFREE) &#123;        /*         * If we race with ep_remove_wait_queue() it can miss         * -&gt;whead = NULL and do another remove_wait_queue() after         * us, so we can&#x27;t use __remove_wait_queue().         */        list_del_init(&amp;wait-&gt;entry);        /*         * -&gt;whead != NULL protects us from the race with ep_free()         * or ep_remove(), ep_remove_wait_queue() takes whead-&gt;lock         * held by the caller. Once we nullify it, nothing protects         * ep/epi or even wait.         */        smp_store_release(&amp;ep_pwq_from_wait(wait)-&gt;whead, NULL);    &#125;    return ewake;&#125;

ep_scan_ready_list()ep_scan_ready_list() 遍历就绪链表 rdllist

1）处理 rdllist 就绪链表。为了减少对 ep-&gt;lock 锁的占用，ep_scan_ready_list() 会先将 rdllist 链表替换出来，然后将 ovflist 赋值为 NULL。后续就绪的事件会添加到 ovflist 链表上，而不用获取锁。
2）处理 ovflist 链表。当 rdllist 链表处理完，接着处理 ovflist 上的就绪链表。处理 ovflist 链表时，lock 锁一直被占用。
3）将处理后的就绪链表，再次替换到 rdllist 链表。此时 rdllist 链表上都是就绪的。

/// fs/eventpoll.cstatic __poll_t ep_scan_ready_list(struct eventpoll *ep,                                   __poll_t (*sproc)(struct eventpoll *,                                    struct list_head *, void *),                                   void *priv, int depth, bool ep_locked)&#123;    __poll_t res;    struct epitem *epi, *nepi;    LIST_HEAD(txlist);    lockdep_assert_irqs_enabled();    if (!ep_locked)        mutex_lock_nested(&amp;ep-&gt;mtx, depth); // 获取 mtx    // 将 rddlist 替换成 txlist 空链表    write_lock_irq(&amp;ep-&gt;lock);    list_splice_init(&amp;ep-&gt;rdllist, &amp;txlist);    WRITE_ONCE(ep-&gt;ovflist, NULL); // 启用 ovflist    write_unlock_irq(&amp;ep-&gt;lock);    // 处理就绪队列    res = (*sproc)(ep, &amp;txlist, priv);    write_lock_irq(&amp;ep-&gt;lock);    // 处理 rdllist 期间，ovflist 可能有新的就绪事件，将其移动到 rdllist    for (nepi = READ_ONCE(ep-&gt;ovflist); (epi = nepi) != NULL;         nepi = epi-&gt;next, epi-&gt;next = EP_UNACTIVE_PTR) &#123;        if (!ep_is_linked(epi)) &#123;            list_add(&amp;epi-&gt;rdllink, &amp;ep-&gt;rdllist); // 添加到 rdlist            ep_pm_stay_awake(epi);        &#125;    &#125;    WRITE_ONCE(ep-&gt;ovflist, EP_UNACTIVE_PTR); // 弃用 ovflist    list_splice(&amp;txlist, &amp;ep-&gt;rdllist); // txlist 添加到 rdlist    __pm_relax(ep-&gt;ws);    if (!list_empty(&amp;ep-&gt;rdllist)) &#123; // rdlist 不为空        if (waitqueue_active(&amp;ep-&gt;wq))            wake_up(&amp;ep-&gt;wq); // 唤醒阻塞在 epoll_wait() 的进程    &#125;    write_unlock_irq(&amp;ep-&gt;lock);    if (!ep_locked)        mutex_unlock(&amp;ep-&gt;mtx);    return res;&#125;

epoll_ctl()epoll_ctl() 负责添加、修改和移除 fd。首先将 fd 集合从用户空间拷贝到内核空间。
/// fs/eventpoll.cSYSCALL_DEFINE4(epoll_ctl, int, epfd, int, op, int, fd,                struct epoll_event __user *, event)&#123;    struct epoll_event epds;    if (ep_op_has_event(op) &amp;&amp;        copy_from_user(&amp;epds, event, sizeof(struct epoll_event)))        return -EFAULT;    return do_epoll_ctl(epfd, op, fd, &amp;epds, false);&#125;

在添加监视事件的时候，首先要保证没有注册过，如果存在，返回 -EEXIST 错误。不过，检测是否注册不仅仅依靠文件描述符，还会查看其绑定的 file 对象的地址。添加到 epoll 的 fd，默认监听 POLLERR 和 POLLHUP 事件。
/// fs/eventpoll.cint do_epoll_ctl(int epfd, int op, int fd, struct epoll_event *epds,                 bool nonblock)&#123;    int error;    int full_check = 0;    struct fd f, tf;    struct eventpoll *ep;    struct epitem *epi;    struct eventpoll *tep = NULL;    error = -EBADF;    f = fdget(epfd); // epoll 绑定的 file    // ...    tf = fdget(fd); // 目标文件绑定的 file    // ...    error = -EINVAL;    if (f.file == tf.file || !is_file_epoll(f.file))        goto error_tgt_fput; // 不能监视自己    // ...    ep = f.file-&gt;private_data;    // ...    epi = ep_find(ep, tf.file, fd); // 在红黑树查找 fd    error = -EINVAL;    switch (op) &#123;        case EPOLL_CTL_ADD:            if (!epi) &#123; // ADD 操作并且没有注册，执行 ep_insert 插入                epds-&gt;events |= EPOLLERR | EPOLLHUP;                error = ep_insert(ep, epds, tf.file, fd, full_check);            &#125; else // 已经存在，返回错误                error = -EEXIST;            break;        case EPOLL_CTL_DEL:             if (epi) // DEL 操作并且存在，执行 ep_remove 删除                error = ep_remove(ep, epi);            else // 不存在，返回错误                error = -ENOENT;            break;        case EPOLL_CTL_MOD:            if (epi) &#123; // MOD 操作并且，存在                if (!(epi-&gt;event.events &amp; EPOLLEXCLUSIVE)) &#123;                    epds-&gt;events |= EPOLLERR | EPOLLHUP;                    error = ep_modify(ep, epi, epds); // 修改 ep_insert                &#125;            &#125; else // 不存在，返回错误                error = -ENOENT;            break;    &#125;    if (tep != NULL)        mutex_unlock(&amp;tep-&gt;mtx);    mutex_unlock(&amp;ep-&gt;mtx);    // ...&#125;

ep_insert()ep_insert() 函数，其函数核心的两个工作是：

将回调函数加入到要监视的文件文件描述符的等待队列上
将要监听事件插入到的红黑树里面

/// fs/eventpoll.cstatic int ep_insert(struct eventpoll *ep, const struct epoll_event *event,                     struct file *tfile, int fd, int full_check)&#123;    int error, pwake = 0;    __poll_t revents;    long user_watches;    struct epitem *epi;    struct ep_pqueue epq;    // ... 分配 epitem    if (!(epi = kmem_cache_alloc(epi_cache, GFP_KERNEL)))        return -ENOMEM;    INIT_LIST_HEAD(&amp;epi-&gt;rdllink);    INIT_LIST_HEAD(&amp;epi-&gt;fllink);    INIT_LIST_HEAD(&amp;epi-&gt;pwqlist);    epi-&gt;ep = ep;    ep_set_ffd(&amp;epi-&gt;ffd, tfile, fd); // 设置监视文件    epi-&gt;event = *event; // 设置监视事件    epi-&gt;nwait = 0;    epi-&gt;next = EP_UNACTIVE_PTR;    if (epi-&gt;event.events &amp; EPOLLWAKEUP) &#123;        error = ep_create_wakeup_source(epi);        if (error)            goto error_create_wakeup_source;    &#125; else &#123;        RCU_INIT_POINTER(epi-&gt;ws, NULL);    &#125;    // 将 epitem 添加到 file 的 f_ep_links 链表中    spin_lock(&amp;tfile-&gt;f_lock);    list_add_tail_rcu(&amp;epi-&gt;fllink, &amp;tfile-&gt;f_ep_links);    spin_unlock(&amp;tfile-&gt;f_lock);    ep_rbtree_insert(ep, epi); // 插入到红黑树    // ... 使用 poll 机制    epq.epi = epi;    init_poll_funcptr(&amp;epq.pt, ep_ptable_queue_proc);    revents = ep_item_poll(epi, &amp;epq.pt, 1); // 获取文件状态    // ... 添加到就绪链表    if (revents &amp;&amp; !ep_is_linked(epi)) &#123;        list_add_tail(&amp;epi-&gt;rdllink, &amp;ep-&gt;rdllist);        ep_pm_stay_awake(epi);        /* Notify waiting tasks that events are available */        if (waitqueue_active(&amp;ep-&gt;wq))            wake_up(&amp;ep-&gt;wq);        if (waitqueue_active(&amp;ep-&gt;poll_wait))            pwake++;    &#125;    write_unlock_irq(&amp;ep-&gt;lock);    atomic_long_inc(&amp;ep-&gt;user-&gt;epoll_watches);    if (pwake)        ep_poll_safewake(ep, NULL);    return 0;    // ...&#125;

ep_ptable_queue_proc() 在调用 ep_scan_ready_list() 函数时，传入了 ep_read_events_proc() 函数。该函数遍历传入的链表，都调用 ep_item_poll() 处理，如果有一个文件就绪，就返回。没有就绪事件的 epi，从就绪链表中删除。
/// fs/eventpoll.cstatic __poll_t ep_read_events_proc(struct eventpoll *ep, struct list_head *head,                                    void *priv)&#123;    struct epitem *epi, *tmp;    poll_table pt;    int depth = *(int *)priv;    init_poll_funcptr(&amp;pt, NULL); // 仅仅获取文件事件状态    depth++;    list_for_each_entry_safe(epi, tmp, head, rdllink) &#123;        if (ep_item_poll(epi, &amp;pt, depth)) &#123; // 有就绪事件，返回            return EPOLLIN | EPOLLRDNORM;        &#125; else &#123; // 没有就绪事件，从就绪队列删除            __pm_relax(ep_wakeup_source(epi));            list_del_init(&amp;epi-&gt;rdllink); // 没有就绪事件，删除        &#125;    &#125;    return 0;&#125;

ep_remove()ep_remove 负责将 fd 从 epoll 中移除。首先取消所有监视的事件，解除和 file 绑定；然后从红黑树中移除；最后从就绪队列（如果存在的话）移除。
/// fs/eventpoll.cstatic int ep_remove(struct eventpoll *ep, struct epitem *epi)&#123;    struct file *file = epi-&gt;ffd.file;    lockdep_assert_irqs_enabled();    // 取消所有监视的事件    ep_unregister_pollwait(ep, epi);    // 和 file 解除绑定    spin_lock(&amp;file-&gt;f_lock);    list_del_rcu(&amp;epi-&gt;fllink);     spin_unlock(&amp;file-&gt;f_lock);    // 从红黑树中移除    rb_erase_cached(&amp;epi-&gt;rbn, &amp;ep-&gt;rbr);    // 从就绪队列 rdllikn 移除    write_lock_irq(&amp;ep-&gt;lock);    if (ep_is_linked(epi))        list_del_init(&amp;epi-&gt;rdllink);    write_unlock_irq(&amp;ep-&gt;lock);    wakeup_source_unregister(ep_wakeup_source(epi));    call_rcu(&amp;epi-&gt;rcu, epi_rcu_free);    atomic_long_dec(&amp;ep-&gt;user-&gt;epoll_watches);    return 0;&#125;

ep_modify()ep_modify() 负责更新 fd 的监视事件。
/// fs/eventpoll.cstatic int ep_modify(struct eventpoll *ep, struct epitem *epi,                     const struct epoll_event *event)&#123;    int pwake = 0;    poll_table pt;    lockdep_assert_irqs_enabled();    init_poll_funcptr(&amp;pt, NULL);    epi-&gt;event.events = event-&gt;events;     epi-&gt;event.data = event-&gt;data;    if (epi-&gt;event.events &amp; EPOLLWAKEUP) &#123;        if (!ep_has_wakeup_source(epi))            ep_create_wakeup_source(epi);    &#125; else if (ep_has_wakeup_source(epi)) &#123;        ep_destroy_wakeup_source(epi);    &#125;    smp_mb();    if (ep_item_poll(epi, &amp;pt, 1)) &#123; // 获取当前文件事件        write_lock_irq(&amp;ep-&gt;lock);        if (!ep_is_linked(epi)) &#123;            list_add_tail(&amp;epi-&gt;rdllink, &amp;ep-&gt;rdllist);            ep_pm_stay_awake(epi);            if (waitqueue_active(&amp;ep-&gt;wq))                wake_up(&amp;ep-&gt;wq);            if (waitqueue_active(&amp;ep-&gt;poll_wait))                pwake++;        &#125;        write_unlock_irq(&amp;ep-&gt;lock);    &#125;    if (pwake)        ep_poll_safewake(ep, NULL);    return 0;&#125;

epoll_wait()epoll_wait() 负责将就绪队列返回给用户，主要的逻辑是调用 ep_poll() 函数。
/// fs/eventpoll.cSYSCALL_DEFINE4(epoll_wait, int, epfd, struct epoll_event __user *, events,                int, maxevents, int, timeout)&#123;    return do_epoll_wait(epfd, events, maxevents, timeout);&#125;static int do_epoll_wait(int epfd, struct epoll_event __user *events,                         int maxevents, int timeout)&#123;    int error;    struct fd f;    struct eventpoll *ep;    // ...    f = fdget(epfd);    // ...    error = -EINVAL;    if (!is_file_epoll(f.file)) // 不是 epoll 文件        goto error_fput;    ep = f.file-&gt;private_data;    error = ep_poll(ep, events, maxevents, timeout); // 主要操作    error_fput:    fdput(f);    return error;&#125;

ep_poll()ep_poll() 函数逻辑如下

设置超时时间，如果超时时间为 0，表示非阻塞，ep_poll() 直接检查就绪队列
调用 ep_events_available() 判断是否存在就绪队列，如果存在就绪队列，调用 ep_send_events() 将就绪事件拷贝到 user 空间返回
不存在就绪队列，将当前调用进程挂在 ep-&gt;wq 等待队列上，然后让出 CPU，等待唤醒

/// fs/eventpoll.cstatic int ep_poll(struct eventpoll *ep, struct epoll_event __user *events,                   int maxevents, long timeout)&#123;    int res = 0, eavail, timed_out = 0;    u64 slack = 0;    wait_queue_entry_t wait;    ktime_t expires, *to = NULL;    lockdep_assert_irqs_enabled();    // 设置超时时间    if (timeout &gt; 0) &#123;        struct timespec64 end_time = ep_set_mstimeout(timeout);        slack = select_estimate_accuracy(&amp;end_time);        to = &amp;expires;        *to = timespec64_to_ktime(end_time);    &#125; else if (timeout == 0) &#123; // 非阻塞，需要立即返回        timed_out = 1;        write_lock_irq(&amp;ep-&gt;lock);        eavail = ep_events_available(ep); // 是否有就绪事件        write_unlock_irq(&amp;ep-&gt;lock);        goto send_events;    &#125;    fetch_events:    if (!ep_events_available(ep))        ep_busy_loop(ep, timed_out); // 和配置有关，是否使用忙等    eavail = ep_events_available(ep);    if (eavail)        goto send_events;    ep_reset_busy_poll_napi_id(ep);    do &#123;        init_wait(&amp;wait);        write_lock_irq(&amp;ep-&gt;lock);        __set_current_state(TASK_INTERRUPTIBLE); // 准备睡眠        // 再次检查一次        eavail = ep_events_available(ep);        if (!eavail) &#123;            if (signal_pending(current))                res = -EINTR;            else                __add_wait_queue_exclusive(&amp;ep-&gt;wq, &amp;wait);        &#125;        write_unlock_irq(&amp;ep-&gt;lock);        if (!eavail &amp;&amp; !res) // 调度，让出 CPU，投入睡眠            timed_out = !schedule_hrtimeout_range(to, slack,                                                  HRTIMER_MODE_ABS);        eavail = 1;    &#125; while (0);    __set_current_state(TASK_RUNNING); // 被唤醒，开始处理    if (!list_empty_careful(&amp;wait.entry)) &#123;        write_lock_irq(&amp;ep-&gt;lock);        if (timed_out)            eavail = list_empty(&amp;wait.entry);        __remove_wait_queue(&amp;ep-&gt;wq, &amp;wait);        write_unlock_irq(&amp;ep-&gt;lock);    &#125;    send_events:    if (fatal_signal_pending(current)) &#123;        res = -EINTR;    &#125;    if (!res &amp;&amp; eavail &amp;&amp;        !(res = ep_send_events(ep, events, maxevents)) &amp;&amp; !timed_out)        goto fetch_events;    return res;&#125;

ep_send_events()如果有就绪事件发生，则调用 ep_send_events() 函数做进一步处理。ep_send_events() 函数调用 ep_send_events_proc() 函数处理 rdllist 就绪队列。
/// fs/eventpoll.cstruct ep_send_events_data &#123;    int maxevents;    struct epoll_event __user *events;    int res;&#125;;static int ep_send_events(struct eventpoll *ep,                          struct epoll_event __user *events, int maxevents)&#123;    struct ep_send_events_data esed;    esed.maxevents = maxevents;    esed.events = events;    ep_scan_ready_list(ep, ep_send_events_proc, &amp;esed, 0, false);    return esed.res;&#125;

ep_send_events_proc() 遍历 rdllink 就绪链表，将就绪的事件拷贝到 user 空间。在拷贝前，再次调用 ep_item_poll() 检查是否真的就绪。
如果采用边缘触发 LT，就绪的事件会被再次添加到 rdllist 链表中。
/// fs/eventpoll.cstatic __poll_t ep_send_events_proc(struct eventpoll *ep, struct list_head *head,                                    void *priv)&#123;    struct ep_send_events_data *esed = priv;    __poll_t revents;    struct epitem *epi, *tmp;    struct epoll_event __user *uevent = esed-&gt;events;    struct wakeup_source *ws;    poll_table pt;    init_poll_funcptr(&amp;pt, NULL); // 仅仅获取文件状态    esed-&gt;res = 0;    lockdep_assert_held(&amp;ep-&gt;mtx);    list_for_each_entry_safe(epi, tmp, head, rdllink) &#123;        if (esed-&gt;res &gt;= esed-&gt;maxevents)            break;        ws = ep_wakeup_source(epi);        if (ws) &#123;            if (ws-&gt;active)                __pm_stay_awake(ep-&gt;ws);            __pm_relax(ws);        &#125;        // 从就绪队列删除        list_del_init(&amp;epi-&gt;rdllink);         // 检查是否真的就绪        revents = ep_item_poll(epi, &amp;pt, 1);        if (!revents)            continue;        if (__put_user(revents, &amp;uevent-&gt;events) ||            __put_user(epi-&gt;event.data, &amp;uevent-&gt;data)) &#123;            list_add(&amp;epi-&gt;rdllink, head); // 出错，重新加入 rdllist            ep_pm_stay_awake(epi);            if (!esed-&gt;res)                esed-&gt;res = -EFAULT; // 返回错误            return 0;        &#125;        esed-&gt;res++;        uevent++;        if (epi-&gt;event.events &amp; EPOLLONESHOT)            epi-&gt;event.events &amp;= EP_PRIVATE_BITS;        else if (!(epi-&gt;event.events &amp; EPOLLET)) &#123;            // LT 触发，重新加入 rdllist            list_add_tail(&amp;epi-&gt;rdllink, &amp;ep-&gt;rdllist);            ep_pm_stay_awake(epi);        &#125;    &#125;    return 0;&#125;

三、动手实践（代码案例）3.1 epoll 基本 ET 模式使用#include &lt;sys/epoll.h&gt;#define MAX_EVENTS 64int epfd = epoll_create1(0);struct epoll_event ev, events[MAX_EVENTS];ev.events = EPOLLIN | EPOLLET;   // 边缘触发ev.data.fd = listen_sock;epoll_ctl(epfd, EPOLL_CTL_ADD, listen_sock, &amp;ev);while (1) &#123;    int nfds = epoll_wait(epfd, events, MAX_EVENTS, -1);    for (int i = 0; i &lt; nfds; i++) &#123;        if (events[i].data.fd == listen_sock) &#123;            int conn = accept(listen_sock, NULL, NULL);            ev.events = EPOLLIN | EPOLLET;            ev.data.fd = conn;            epoll_ctl(epfd, EPOLL_CTL_ADD, conn, &amp;ev);        &#125; else &#123;            char buf[4096];            while (1) &#123;  // ET 模式必须循环读到 EAGAIN                ssize_t n = read(events[i].data.fd, buf, sizeof(buf));                if (n &lt;= 0) break;                // 处理 buf...            &#125;        &#125;    &#125;&#125;

3.2 EPOLLONESHOT 多线程安全模式// 注册 ONESHOT，一次就绪后自动挂起ev.events = EPOLLIN | EPOLLET | EPOLLONESHOT;ev.data.ptr = conn_ptr;  // 存储连接对象指针epoll_ctl(epfd, EPOLL_CTL_ADD, conn_fd, &amp;ev);// 工作线程处理完后重新激活ev.events = EPOLLIN | EPOLLET | EPOLLONESHOT;epoll_ctl(epfd, EPOLL_CTL_MOD, conn_fd, &amp;ev);

四、进阶应用（≥500字）4.1 Reactor 模式中的 epoll 角色epoll 是 Reactor（事件分发器）模式在 Linux 上的最佳底层实现。核心设计：通过 epoll_event.data.ptr 直接存储 handler 指针，避免 fd→handler 的查找开销。
4.2 EPOLLEXCLUSIVE 解决惊群Linux 4.5+ 引入 EPOLLEXCLUSIVE：多线程 epoll_wait 同一 epfd 且监听 fd 标记该标志时，内核只唤醒一个线程：
ev.events = EPOLLIN | EPOLLEXCLUSIVE;epoll_ctl(epfd, EPOLL_CTL_ADD, listen_fd, &amp;ev);// 多个线程 epoll_wait 同一 epfd 时，只有一个被唤醒处理 accept

