五、源码解析和实践感悟（≥1000字）5.1 ep_insert 核心流程/// fs/eventpoll.cstatic int ep_insert(struct eventpoll *ep, const struct epoll_event *event,                     struct file *tfile, int fd, int full_check)&#123;    struct epitem *epi;    struct ep_pqueue epq;    // 1. 分配 epitem（从 slab 缓存）    epi = kmem_cache_alloc(epi_cache, GFP_KERNEL);    INIT_LIST_HEAD(&amp;epi-&gt;rdllink);    epi-&gt;ep = ep;    ep_set_ffd(&amp;epi-&gt;ffd, tfile, fd);    epi-&gt;event = *event;    // 2. 加入 file-&gt;f_ep_links（双向关联：file ↔ epitem）    list_add_tail_rcu(&amp;epi-&gt;fllink, &amp;tfile-&gt;f_ep_links);    // 3. 插入红黑树    ep_rbtree_insert(ep, epi);    // 4. 设置回调函数并通过 vfs_poll 检查当前状态    epq.epi = epi;    init_poll_funcptr(&amp;epq.pt, ep_ptable_queue_proc);    revents = ep_item_poll(epi, &amp;epq.pt, 1);    // 5. 如果已经就绪，直接加入就绪链表    if (revents &amp;&amp; !ep_is_linked(epi)) &#123;        list_add_tail(&amp;epi-&gt;rdllink, &amp;ep-&gt;rdllist);        if (waitqueue_active(&amp;ep-&gt;wq)) wake_up(&amp;ep-&gt;wq);    &#125;    return 0;&#125;

关键设计：注册时立即调用 vfs_poll 获取当前状态——如果 fd 已经可读&#x2F;可写，直接加入就绪链表。
5.2 ep_poll_callback 事件驱动核心static int ep_poll_callback(wait_queue_entry_t *wait, unsigned mode,                            int sync, void *key)&#123;    struct epitem *epi = ep_item_from_wait(wait);    struct eventpoll *ep = epi-&gt;ep;    __poll_t pollflags = key_to_poll(key);        // 过滤非关注事件    if (pollflags &amp;&amp; !(pollflags &amp; epi-&gt;event.events))        goto out_unlock;        // rdllist 空闲→直接加入；被占用→加入 ovflist    if (READ_ONCE(ep-&gt;ovflist) != EP_UNACTIVE_PTR) &#123;        chain_epi_lockless(epi);       // 无锁加入备用队列    &#125; else if (!ep_is_linked(epi)) &#123;        list_add_tail_lockless(&amp;epi-&gt;rdllink, &amp;ep-&gt;rdllist);    &#125;    // 唤醒阻塞在 epoll_wait 的进程    if (waitqueue_active(&amp;ep-&gt;wq)) wake_up(&amp;ep-&gt;wq);    // 唤醒监视此 epoll 的其他 epoll 实例    if (waitqueue_active(&amp;ep-&gt;poll_wait)) pwake++;    return ewake;&#125;

5.3 ep_send_events_proc LT&#x2F;ET 的实现差异static __poll_t ep_send_events_proc(struct eventpoll *ep,    struct list_head *head, void *priv)&#123;    list_for_each_entry_safe(epi, tmp, head, rdllink) &#123;        list_del_init(&amp;epi-&gt;rdllink);  // 先从就绪链表移除        revents = ep_item_poll(epi, &amp;pt, 1);  // 再次确认就绪        if (!revents) continue;                // 拷贝到用户空间        __put_user(revents, &amp;uevent-&gt;events);        __put_user(epi-&gt;event.data, &amp;uevent-&gt;data);                if (epi-&gt;event.events &amp; EPOLLONESHOT)            epi-&gt;event.events &amp;= EP_PRIVATE_BITS;   // 挂起        else if (!(epi-&gt;event.events &amp; EPOLLET)) &#123;            // LT 模式：重新加入就绪链表            list_add_tail(&amp;epi-&gt;rdllink, &amp;ep-&gt;rdllist);        &#125;        // ET 模式：不再重新加入    &#125;    return 0;&#125;

5.4 ep_scan_ready_list 双缓冲区并发设计这个函数体现了内核并发设计的高水准：

取出阶段：将 rdllist 替换为 txlist，启用 ovflist（此时锁释放，新事件无锁流入 ovflist）
处理阶段：遍历 txlist 中的就绪事件，拷贝到用户空间
合并阶段：将 ovflist 中的新事件合并回 rdllist

设计精髓：处理期间释放锁，极大减少锁竞争，同时 ovflist 保证不丢事件。
5.5 实践感悟与易错点
ET 模式的核心陷阱：边缘触发只在状态变化时通知一次。如果只调用一次 read 而没有循环读到 EAGAIN，缓冲区剩余数据永远不会触发新通知 → 数据永久丢失。正确代码示例见 3.1。

fd 关闭前必须 epoll_ctl DEL：内核在 fd 关闭时会自动移除关联的 epitem（通过 file-&gt;f_ep_links 链表），但若后续 socket() 复用了同一 fd 编号，旧 epitem 可能指向新的 file 对象 → 未定义行为。

epoll_create 的 size 参数已废弃：Linux 2.6.8 后内核动态管理红黑树，size 仅需 &gt; 0。所有关于 size 限制 fd 数量 的说法均已过时。

惊群问题：多线程 epoll_wait 同一 epfd + 同一 listen fd → 所有线程被唤醒竞争 accept。Linux 4.5+ EPOLLEXCLUSIVE 是标准解决方案，低版本需在 accept 前加锁。

epoll_event.data 的设计智慧：使用 union 支持 fd、ptr、u32、u64 四种模式，允许直接存储对象指针（data.ptr = conn），避免额外的 fd→handler 查找。


可以看到，select(2) 和 poll(2) 也利用了虚拟文件系统poll 机制，只不过仅仅是唤醒 do_select() 或者 do_poll() 进程，而 epoll(7) 的实现中就绪文件不仅唤醒 epoll_wait(2) 进程，在这之前还将就绪的事件添加到就绪的队列，减少了唤醒之后的遍历所有文件描述符检查就绪工作，而是仅仅检查处于就绪链表上的事件，复杂度大大减少。
