常见设计模式虚函数实战案例小彭老师，你说的这些我都会，这有什么稀奇的。那我们来举个实际开发中会遇到的例子。
这里有一个求和函数，可以计算一个数组中所有数字的和。 还有一个求积函数，可以计算一个数组中所有数字的积。
int sum(vector&lt;int&gt; v) &#123;    int res = 0;    for (int i = 0; i &lt; v.size(); i++) &#123;        res = res + v[i];    &#125;    return res;&#125;int product(vector&lt;int&gt; v) &#123;    int res = 1;    for (int i = 0; i &lt; v.size(); i++) &#123;        res = res * v[i];    &#125;    return res;&#125;

注意到这里面有很多代码重复！
我们观察一下 sum 和 product 之间有哪些相似的部分，把两者产生不同的部分用 ??? 代替。
int reduce(vector&lt;int&gt; v) &#123;    int res = ???;            // sum 时这里是 0，product 时这里是 1    for (int i = 0; i &lt; v.size(); i++) &#123;        res = res ??? v[i];   // sum 时这里是 +，product 时这里是 *    &#125;    return res;&#125;

把 ??? 部分用一个虚函数顶替：
struct Reducer &#123;    virtual int init() = 0;    virtual int add(int a, int b) = 0;&#125;;int reduce(vector&lt;int&gt; v, Reducer *reducer) &#123;    int res = reducer-&gt;init();    for (int i = 0; i &lt; v.size(); i++) &#123;        res = reducer-&gt;add(res, v[i]);    &#125;    return res;&#125;

这样不论我们想要求和，还是求积，只需要实现其中不同的部分就可以了，公共部分已经在 reduce 里实现好，就实现了代码复用。
struct SumReducer : Reducer &#123;    int init() override &#123;        return 0;    &#125;    int add(int a, int b) override &#123;        return a + b;    &#125;&#125;;struct ProductReducer : Reducer &#123;    int init() override &#123;        return 1;    &#125;    int add(int a, int b) override &#123;        return a * b;    &#125;&#125;;

reduce(v, new SumReducer());     // 等价于之前的 sum(v)reduce(v, new ProductReducer()); // 等价于之前的 product(v)

这就是所谓的策略模式。
很容易添加新的策略进来：
struct MinReducer : Reducer &#123;    int init() override &#123;        return numeric_limits&lt;int&gt;::max();    &#125;    int add(int a, int b) override &#123;        return min(a, b);    &#125;&#125;;struct MaxReducer : Reducer &#123;    int init() override &#123;        return numeric_limits&lt;int&gt;::min();    &#125;    int add(int a, int b) override &#123;        return max(a, b);    &#125;&#125;;

多重策略现在，老板需求改变，他想要 sum 和 product 函数从输入数据直接计算（而不用先读取到一个 vector）！
还好你早已提前抽出公共部分，现在只需要修改 reduce 函数本身就可以了。
SumReducer 和 ProductReducer 无需任何修改，体现了开闭原则。
int reduce(Reducer *reducer) &#123;    int res = reducer-&gt;init();    while (true) &#123;        int tmp;        cin &gt;&gt; tmp;        if (tmp == -1) break;        res = reducer-&gt;add(res, tmp);    &#125;    return res;&#125;

现在，老板需求又改回来，他突然又想要从 vector 里读取数据了。
在破口大骂老板出尔反尔的同时，你开始思考，这两个函数似乎还是有一些重复可以抽取出来？
int cin_reduce(Reducer *reducer) &#123;    int res = reducer-&gt;init();    while (true) &#123;        int tmp;        cin &gt;&gt; tmp;        if (tmp == -1) break;        res = reducer-&gt;add(res, tmp);    &#125;    return res;&#125;int vector_reduce(vector&lt;int&gt; v, Reducer *reducer) &#123;    int res = reducer-&gt;init();    for (int i = 0; i &lt; v.size(); i++) &#123;        res = reducer-&gt;add(res, v[i]);    &#125;    return res;&#125;

现在我们只有表示如何计算的类 Reducer 做参数。
你决定，再定义一个表示如何读取的虚类 Inputer。
struct Inputer &#123;    virtual optional&lt;int&gt; fetch() = 0;&#125;;int reduce(Inputer *inputer, Reducer *reducer) &#123;    int res = reducer-&gt;init();    while (auto tmp = inputer-&gt;fetch()) &#123;        res = reducer-&gt;add(res, tmp.value());    &#125;    return res;&#125;

这样，我们满足了单一职责原则：每个类只负责一件事。
这里的 Inputer 实际上运用了迭代器模式：提供一个抽象接口来顺序访问一个集合中各个元素，而又无须暴露该集合的内部表示。
底层是 cin 还是 vector？我不在乎！我只知道他可以依次顺序取出数据。
struct CinInputer : Inputer &#123;    optional&lt;int&gt; fetch() override &#123;        int tmp;        cin &gt;&gt; tmp;        if (tmp == -1)            return nullopt;        return tmp;    &#125;&#125;;struct VectorInputer : Inputer &#123;    vector&lt;int&gt; v;    int pos = 0;    VectorInputer(vector&lt;int&gt; v) : v(v) &#123;&#125;    optional&lt;int&gt; fetch() override &#123;        if (pos == v.size())            return nullopt;        return v[pos++];    &#125;&#125;;

reduce(new CinInputer(), new SumReducer());reduce(new VectorInputer(v), new SumReducer());reduce(new CinInputer(), new ProductReducer());reduce(new VectorInputer(v), new ProductReducer());

Inputer 负责告诉 reduce 函数如何读取数据，Reducer 负责告诉 reduce 函数如何计算数据。
这就是依赖倒置原则：高层模块（reduce 函数）不要直接依赖于低层模块，二者都依赖于抽象（Inputer 和 Reducer 类）来沟通。
适配器模式刚才的例子中我们用到了 Inputer 虚接口类。
struct CinInputer : Inputer &#123;    optional&lt;int&gt; fetch() override &#123;        int tmp;        cin &gt;&gt; tmp;        if (tmp == -1)            return nullopt;        return tmp;    &#125;&#125;;struct VectorInputer : Inputer &#123;    vector&lt;int&gt; v;    int pos = 0;    VectorInputer(vector&lt;int&gt; v) : v(v) &#123;&#125;    optional&lt;int&gt; fetch() override &#123;        if (pos == v.size())            return nullopt;        return v[pos++];    &#125;&#125;;

如果我们想要实现：读取到 0 截止，而不是 -1 呢？难道还得给 CinInputer 加个参数？ 但是 vector 有时候也可能有读到 -1 就提前截断的需求呀？
这明显违背了单一责任原则。
更好的设计是，让 CinInputer 无限读取，永远成功。 然后另外弄一个 StopInputerAdapter，其接受一个 CinInputer 作为构造参数。 当 StopInputerAdapter 被读取时，他会检查是否为 -1，如果已经得到 -1，那么就返回 nullopt，不会进一步调用 CinInputer 了。
StopInputerAdapter 负责处理截断问题，CinInputer 只是负责读取 cin 输入。满足了单一责任原则。
struct StopInputerAdapter : Inputer &#123;    Inputer *inputer;    int stopMark;    StopInputerAdapter(Inputer *inputer, int stopMark)        : inputer(inputer)        , stopMark(stopMark)    &#123;&#125;    optional&lt;int&gt; fetch() override &#123;        auto tmp = inputer-&gt;fetch();        if (tmp == stopMark)            return nullopt;        return tmp;    &#125;&#125;;

这里的 StopInputerAdapter 就是一个适配器，他把 CinInputer 的接口（无限读取）叠加上了一个额外功能，读到指定的 stopMark 值就停止，产生了一个新的 Inputer。
reduce(new StopInputerAdapter(new CinInputer(), -1), new SumReducer());      // 从 cin 读到 -1 为止reduce(new StopInputerAdapter(new VectorInputer(v), -1), new SumReducer());  // 从 vector 读到 -1 为止reduce(new VectorInputer(), new SumReducer());  // 从 vector 读，但无需截断

这就是适配器模式：将一个类的接口添油加醋，转换成客户希望的另一个接口。

StopInputerAdapter 这个适配器本身也是一个 Inputer，可以直接作为 reduce 的参数，适应了现有的策略模式。
StopInputerAdapter 并不依赖于参数 Inputer 的底层实现，可以是 CinInputer、也可以是 VectorInputer，满足了依赖倒置原则。
未来即使新增了不同类型的 Inputer，甚至是其他 InputerAdapter，一样可以配合 StopInputerAdapter 一起使用而无需任何修改，满足了开闭原则。

工厂模式现在你是一个游戏开发者，你的玩家可以装备武器，不同的武器可以发出不同的子弹！
你使用小彭老师教的策略模式，把不同的子弹类型作为不同的策略传入 player 函数，造成不同类型的伤害。
struct Bullet &#123;    virtual void explode() = 0;&#125;;struct AK47Bullet : Bullet &#123;    void explode() override &#123;        puts(&quot;物理伤害&quot;);    &#125;&#125;;struct MagicBullet : Bullet &#123;    void explode() override &#123;        puts(&quot;魔法伤害&quot;);    &#125;&#125;;void player(Bullet *bullet) &#123;    bullet-&gt;explode();&#125;player(new AK47Bullet());player(new MagicBullet());

但是这样就相当于每个玩家只有一发子弹，听个响就没了…
如何允许玩家源源不断地创造新子弹出来？我们可以把“创建子弹”这一过程抽象出来，放在一个“枪”类里。
struct Gun &#123;    virtual Bullet *shoot() = 0;&#125;;struct AK47Gun : Gun &#123;    Bullet *shoot() override &#123;        return new AK47Bullet();    &#125;&#125;;struct MagicGun : Gun &#123;    Bullet *shoot() override &#123;        return new MagicBullet();    &#125;&#125;;void player(Gun *gun) &#123;    for (int i = 0; i &lt; 100; i++) &#123;        Bullet *bullet = gun-&gt;shoot();        bullet-&gt;explode();    &#125;&#125;player(new AK47Gun());player(new MagicGun());

现在，你的玩家可以直接选择不同的枪了！
这就是所谓的工厂模式：“枪”就是“子弹”对象的工厂。 传给玩家的是子弹的工厂——枪，而不是子弹本身。 只要调用工厂的 shoot 函数，玩家可以源源不断地创建新子弹出来。 正所谓授人以鱼不如授人以渔，你的玩家不再是被动接受子弹，而是可以自己创造子弹了！
工厂还可以具有一定的参数，例如我们需要模拟 AK47 可能“受潮”，导致产生的子弹威力降低。 就可以给枪加一个 isWet 参数，给子弹加一个 damage 参数，让 AK47 生成子弹的时候，根据 isWet 为子弹构造函数设置不同的 damage。
struct AK47Bullet &#123;    int damage;    AK47Bullet(int damage) : damage(damage) &#123;&#125;    void explode() &#123;        printf(&quot;造成 %d 点物理伤害\n&quot;, damage);    &#125;&#125;;struct AK47Gun : Gun &#123;    bool isWet;    AK47Gun(bool isWet) : isWet(isWet) &#123;&#125;    Bullet *shoot() override &#123;        if (isWet)            return new AK47Bullet(5);  // 受潮了，伤害降低为 5        else            return new AK47Bullet(10); // 正常情况下伤害为 10    &#125;&#125;;

我们还可以利用模板自动为不同的子弹类型批量定义工厂：
template &lt;class B&gt;struct GunWithBullet : Gun &#123;    static_assert(is_base_of&lt;Bullet, B&gt;::value, &quot;B 必须是 Bullet 的子类&quot;);    Bullet *shoot() override &#123;        return new B();    &#125;&#125;;void player(Gun *gun) &#123;    for (int i = 0; i &lt; 100; i++) &#123;        Bullet *bullet = gun-&gt;shoot();        bullet-&gt;explode();    &#125;&#125;player(new GunWithBullet&lt;AK47Bullet&gt;());player(new GunWithBullet&lt;MagicBullet&gt;());

RAII 自动管理内存template &lt;class B&gt;struct GunWithBullet : Gun &#123;    static_assert(is_base_of&lt;Bullet, B&gt;::value, &quot;B 必须是 Bullet 的子类&quot;);    Bullet *shoot() override &#123;        return new B();    &#125;&#125;;void player(Gun *gun) &#123;    for (int i = 0; i &lt; 100; i++) &#123;        Bullet *bullet = gun-&gt;shoot();        bullet-&gt;explode();        delete bullet;  // 刚才没有 delete！会产生内存泄漏！    &#125;&#125;player(new GunWithBullet&lt;AK47Bullet&gt;());player(new GunWithBullet&lt;MagicBullet&gt;());

现在的工厂一般都会返回智能指针就没有这个问题。
具体来说就是用 unique_ptr&lt;T&gt; 代替 T *，用 make_unique&lt;T&gt;(xxx) 代替 new T(xxx)。
template &lt;class B&gt;struct GunWithBullet : Gun &#123;    static_assert(is_base_of&lt;Bullet, B&gt;::value, &quot;B 必须是 Bullet 的子类&quot;);    unique_ptr&lt;Bullet&gt; shoot() override &#123;        return make_unique&lt;B&gt;();    &#125;&#125;;void player(Gun *gun) &#123;    for (int i = 0; i &lt; 100; i++) &#123;        auto bullet = gun-&gt;shoot();        bullet-&gt;explode();        // unique_ptr 在退出当前 &#123;&#125; 时会自动释放，不用你惦记着了    &#125;&#125;player(make_unique&lt;GunWithBullet&lt;AK47Bullet&gt;&gt;().get());player(make_unique&lt;GunWithBullet&lt;MagicBullet&gt;&gt;().get());

这里 C++ 标准保证了 unique_ptr 的生命周期是这一整行（; 结束前），整个 player 执行期间都活着，不会提前释放 正如 func(string().c_str()) 不会有任何问题，string 要到 func 返回后才释放呢！
只要把所有 make_unique&lt;T&gt; 看作 new T，把所有的 unique_ptr&lt;T&gt; 看作 T *，用法几乎一样，但没有内存泄漏，无需手动 delete。
享元模式在二维游戏开发中，常常会提到一种称为 Sprite（精灵贴图）的黑话，实际上就是每个对象自己有一张贴图，贴图跟着物体的位置走。
struct Bullet &#123;    glm::vec3 position;    glm::vec3 velocity;    vector&lt;char&gt; texture;    void draw() &#123;        glDrawPixels(position, texture);    &#125;&#125;;

texture 里面存储着贴图的 RGB 数据，他直接就是 Bullet 的成员。 这样的话，如果我们的玩家打出了 100 颗子弹，就需要存储 100 个贴图数组。 如果我们的玩家同时打出了 1000 颗子弹，就需要存储 1000 个贴图数组。 这样的话，内存消耗将会非常大。然而所有同类型的 Bullet，其贴图数组其实是完全相同的，完全没必要各自存那么多份拷贝。
为解决这个问题，我们可以使用享元模式：共享多个对象之间相同的部分，节省内存开销。
这里每颗子弹的 position、velocity 显然都是各有不同的，不可能所有子弹都在同一个位置上。 但是很多子弹都会有着相同的贴图，只有不同类型的子弹贴图会不一样。 比如火焰弹和寒冰弹会有不同的贴图，但是当场上出现 100 颗火焰弹时，显然不需要拷贝 100 份完全相同的火焰弹贴图。
struct Sprite &#123;  // Sprite 才是真正持有（很大的）贴图数据的    vector&lt;char&gt; texture;    void draw(glm::vec3 position) &#123;        glDrawPixels(position, texture);    &#125;&#125;;struct Bullet &#123;    glm::vec3 position;    glm::vec3 velocity;    shared_ptr&lt;Sprite&gt; sprite;  // 允许多个子弹对象共享同一个精灵贴图的所有权    void draw() &#123;        sprite-&gt;draw(position);  // 转发给 Sprite 让他帮忙在我的位置绘制贴图    &#125;&#125;;

需要绘制子弹时，Bullet 的 draw 只是简单地转发给 Sprite 类的 draw。 只要告诉 Sprite 子弹的位置就行，贴图数据已经存在 Sprite 内部，让他来负责真正绘制。 Bullet 类只需要专注于位置、速度的更新即可，不必去操心着贴图绘制的细节，实现了解耦。
这种函数调用的转发也被称为代理模式。
代理模式这样还有一个好处那就是，Sprite 可以设计成一个虚函数接口类：
struct Sprite &#123;    virtual void draw(glm::vec3 position) = 0;&#125;;struct FireSprite : Sprite &#123;    vector&lt;char&gt; fireTexture;    FireSprite() : fireTexture(loadTexture(&quot;fire.jpg&quot;)) &#123;&#125;    void draw(glm::vec3 position) override &#123;        glDrawPixels(position, fireTexture);    &#125;&#125;;struct IceSprite : Sprite &#123; // 假如寒冰弹需要两张贴图，也没问题！因为虚接口类允许子类有不同的成员，不同的结构体大小    vector&lt;char&gt; iceTexture1;    vector&lt;char&gt; iceTexture2;    IceSprite()    : iceTexture1(loadTexture(&quot;ice1.jpg&quot;))    , iceTexture2(loadTexture(&quot;ice2.jpg&quot;))    &#123;&#125;    void draw(glm::vec3 position) override &#123;        glDrawPixels(position, iceTexture1);        glDrawPixels(position, iceTexture2);    &#125;&#125;;

struct Bullet &#123;    glm::vec3 position;    glm::vec3 velocity;    shared_ptr&lt;Sprite&gt; sprite;  // Sprite 负责含有虚函数    void draw() &#123;  // Bullet 的 draw 就不用是虚函数了！        sprite-&gt;draw(position);    &#125;&#125;;

单例模式通常用于游戏中的全局管理类，保证整个程序（进程）中只有一个实例对象存在。有很多种常见的写法：

作为全局变量（饿汗模式）

Game game;

效果：在程序启动时就会创建 game 对象，之后可以直接使用。

作为函数内部的 static 变量（懒汗模式）

Game &amp;getGame() &#123;    static Game game;    return game;&#125;getGame().updatePlayers();

效果：第一次调用 getGame() 时会初始化，之后的调用会直接返回上次创建的实例。
根据你的需要，如果你需要在程序一启动时 game 对象就可用，就用饿汗模式。
如果 game 的初始化需要某些条件，例如创建 Game 类前需要 OpenGL 初始化，那么可用懒汗模式：
int main() &#123;    glfwInit();                 // 初始化 OpenGL    getGame().initialize();     // 第一次调用 getGame 会初始化 game 单例    getGame().updatePlayers();  // 之后的调用总是返回对同一个 game 单例的引用&#125;

提示：如果要把单例对象的定义放在头文件中，务必添加 inline 修饰符，而不是 static，否则会导致多个 cpp 文件各自有一个 Game 对象。
// Game.hppinline Game game;inline Game &amp;getGame() &#123;    static Game game;    return game;&#125;

封装在类内部由于所有单例全部暴露在全局名字空间，容易产生混乱。 一般会把单例对象或函数封装在类内部，并且把 Game 的构造函数设为 private，避免用户不慎直接创建出本应只有单个实例的 Game 类。

作为全局变量（饿汗模式）

struct Game &#123;    ...    Game(Game &amp;&amp;) = delete;private:    Game() &#123; ... &#125;public:    // inline static Game instance;  // 虽然很爽，但不能这样写，因为 Game 在他的 &#125;; 结束前都是不完整类型    static Game instance;  // 非定义声明，就好比全局变量的 extern Game instance 一样，不需要是完整类型&#125;;inline Game Game::instance;  // 如果定义在头文件中，需要 inline！Game::instance.updatePlayers();

警告：只定义在头文件中并使用 inline 这种写法，不适用于多 DLL 的情况！这会使 DLL 和 EXE 各自持有一份互不共通的 instance。如果需要在多 DLL 环境中使用这种饿汗模式单例，请乖乖分离声明和定义，别用 inline 了。
这是因为 Windows 中的每个 DLL 和 EXE 都是一座孤岛，互相不知道对方有没有这个符号，所以 inline 的效果从“全局只保留一份定义”变成在每个“孤岛”内各自在内部只保留一份，从而 DLL 和 EXE 各自一份，总共有两份了，互相内容不互通，从而不是单例模式。而 Linux 没有这个问题，因为 SO 动态库是运行时才由 ld-linux.so 完成链接的，SO 内部仍保有编译时产生的函数符号信息，为的是被可执行 ELF 加载进来以后，ld-linux.so 可以自动根据把可执行 ELF 和 SO 内部的 call 指令后的地址更新为加载后的符号的动态地址。而 Windows 的 DLL 中所有符号在编译时就已经被 ld 已经焊死，无法修改，这就是为什么 Windows 的每个 DLL 都会自动额外生成一个同名 LIB 文件，这个 LIB 里面实际上是一个个“插桩”函数，这些函数名字和 DLL 中的相同，但是函数的内容，是会动态 LoadLibrary 加载同名 DLL，并通过 GetProcAddress 动态获取所有 dllexport 的函数，而链接时候指定的实际上是原 DLL 对应的这个插桩 LIB，DLL 本身是无法被链接器链接的。

作为函数内部的 static 变量（懒汗模式）

struct Game &#123;    ...    Game(Game &amp;&amp;) = delete;private:    Game() &#123; ... &#125;public:    inline static Game &amp;instance() &#123;  // 这里的 inline 可以省略，因为类体内就地实现的函数自带 inline 效果        static Game game;        return game;    &#125;&#125;;Game::instance().updatePlayers();

警告：这种写法同样不适用于多 DLL 的情况！如果需要在多 DLL 环境中使用，请乖乖分离声明和定义。
通用的单例模式模板template &lt;class T&gt;inline T &amp;singleton() &#123;  // 这里的 inline 可以省略，因为就地实现的模板函数自带 inline 效果    // 只有第一次进入时会构造一遍 T，之后不会再构造    // 不同的 T 会实例化出不同的 singleton 实例，各自体内的 static 变量独立计算，互不干扰    static T inst;    return inst;&#125;singleton&lt;Game&gt;().updatePlayers();singleton&lt;Other&gt;().someMethod();

任何类型 T，只要以 singleton&lt;T&gt;() 形式获取，都能保证每个 T 都只有一份对象。（前提是你不要再 T() 创建对象）
警告：这种写法同样不适用于多 DLL 的情况！如果需要在多 DLL 环境中使用，请乖乖分离模板的声明和定义。
模板模式注意：模板模式和 C++ 的模板并没有必然关系！模板模式只是一种思想，可以用模板实现，也可以用虚函数实现（大多反而是用虚函数实现的）
模板模式用于封装游戏中一些相似的处理逻辑，把共同的部分集中到一个基类，把不同的细节部分留给子类实现。
和策略模式很像，只不过这里接收策略的直接就是基类自己。
例如，一个角色固定每一帧需要移动 3 次，然后绘制 1 次。显然需要把“移动”和“绘制”作为两个虚函数接口，让子类来实现。
struct Character &#123;    virtual void draw() = 0;    virtual void move() = 0;&#125;;struct Player : Character &#123;    void draw() override &#123;        drawPlayer();    &#125;    void move() override &#123;        movePlayer();    &#125;&#125;;struct Enemy : Character &#123;    void draw() override &#123;        drawEnemy();    &#125;    void move() override &#123;        moveEnemy();    &#125;&#125;;

如果让负责调用 Character 的人来实现每一帧需要移动 3 次 + 绘制 1 次的话，就破坏了开闭原则。
struct Game &#123;    vector&lt;Character *&gt; chars;    void update() &#123;        for (auto &amp;&amp;c: chars) &#123;            c-&gt;move();            c-&gt;move();            c-&gt;move();            c-&gt;draw();        &#125;    &#125;&#125;

改为把移动 3 次 + 绘制 1 次封装为一个 Character 的普通函数 update。
struct Character &#123;protected:    virtual void draw() = 0;    virtual void move() = 0;public:    void update() &#123;        move();        move();        move();        draw();    &#125;&#125;;struct Game &#123;    vector&lt;Character *&gt; chars;    void update() &#123;        for (auto &amp;&amp;c: chars) &#123;            c-&gt;update();        &#125;    &#125;&#125;

这样调用者就很轻松了，不必关心底层细节，而 update 也只通过接口和子类通信，满足开闭原则和依赖倒置原则。
模板模式还是策略模式：如何选择？当一个对象涉及很多策略时，用策略模式；当只需要一个策略，且需要用到基类的成员时，用模板模式。
例如，一个角色的策略有移动策略和攻击策略，移动方式有“走路”、“跑步”两种，攻击策略又有“平A”、“暴击”两种。
那么就用策略模式，让角色分别指向移动策略和攻击策略的指针。
struct Character &#123;    MoveStrategy *moveStrategy;    AttackStrategy *attackStrategy;    void update() &#123;        if (isKeyPressed(GLFW_KEY_S) &#123;            moveStrategy-&gt;move();        &#125; else if (isKeyPressed(GLFW_KEY_W)) &#123;            moveStrategy-&gt;run();        &#125;        while (auto enemy = Game::instance().findEnemy(range)) &#123;            attackStrategy-&gt;attack(enemy);        &#125;    &#125;&#125;;

而如果只有一个策略，比如武器类，只需要攻击策略，并且攻击策略需要知道武器的伤害值、射程、附魔属性等信息，那就适合模板模式。
struct Weapon &#123;protected:    double damage;    double charge;    MagicFlag magicFlags;    double range;    virtual void attack(Enemy *enemy);public:    void update() &#123;        while (auto enemy = Game::instance().findEnemy(range)) &#123;            attack(enemy);        &#125;    &#125;&#125;;

最常见的是 do_xxx 封装例如，一个处理字符串的虚接口类：
struct Converter &#123;    virtual void process(const char *s, size_t len) = 0;&#125;;

这个接口是考虑 实现 Converter 子类的方便，对于 调用 Converter 的用户 使用起来可能并不方便。
这时候就可以运用模板模式，把原来的虚函数接口改为 protected 的函数，且名字改为 do_process。
struct Converter &#123;protected:    virtual void do_process(const char *s, size_t len) = 0;public:    void process(string_view str) &#123;        return do_process(str.data(), str.size());    &#125;    void process(string str) &#123;        return do_process(str.data(), str.size());    &#125;    void process(const char *cstr) &#123;        return do_process(cstr, strlen(cstr));    &#125;&#125;;

实现 Converter 的子类时，重写他的 do_process 函数，这些函数是 protected 的，只能被继承了 Converter 的子类访问和重写。
外层用户只能通过 Converter 基类封装好的 process 函数，避免外层用户直接干涉底层细节。
标准库中的 std::pmr::memory_resource、std::codecvt 等都运用了 do_xxx 式的模板模式封装。
状态模式游戏中的角色通常有多种状态，例如，一个怪物可能有“待机”、“巡逻”、“追击”、“攻击”等多种状态，而每种状态下的行为都不一样。
如果用一个枚举变量来表示当前状态，那每次就都需要用 switch 来处理不同的状态。
enum MonsterState &#123;    Idle,    Chase,    Attack,&#125;;struct Monster &#123;    MonsterState state = Idle;    void update() &#123;        switch (state) &#123;            case Idle:                if (seesPlayer())                    state = Chase;                break;            case Chase:                if (canAttack())                    state = Attack;                else if (!seesPlayer())                    state = Idle;                break;            case Attack:                if (!seesPlayer())                    state = Idle;                break;        &#125;    &#125;&#125;;

这或许性能上有一定优势，缺点是，所有不同状态的处理逻辑堆积在同一个函数中，如果有多个函数（不只是 update），那么每添加一个新状态就需要修改所有函数，不符合开闭原则。
而且如果不同的状态含有不同的额外数值需要存储，比如 Chase 状态需要存储当前速度，那就需要在 Monster 类中添加 speed 成员，而 state 不为 Chase 时又用不到这个成员，非常容易扰乱思维。
状态不是枚举，而是类为此，提出了状态模式，将不同状态的处理逻辑分离到不同的类中。他把每种状态抽象为一个类，状态是一个对象，让角色持有表示当前状态的对象，用状态对象的虚函数来表示处理逻辑，而不必每次都通过 if 判断来执行不同的行为。
struct Monster;struct State &#123;    virtual void update(Monster *monster) = 0;&#125;;struct Idle : State &#123;    void update(Monster *monster) override &#123;        if (monster-&gt;seesPlayer()) &#123;            monster-&gt;setState(new Chase());        &#125;    &#125;&#125;;struct Chase : State &#123;    void update(Monster *monster) override &#123;        if (monster-&gt;canAttack()) &#123;            monster-&gt;setState(new Attack());        &#125; else if (!monster-&gt;seesPlayer()) &#123;            monster-&gt;setState(new Idle());        &#125;    &#125;&#125;;struct Attack : State &#123;    void update(Monster *monster) override &#123;        if (!monster-&gt;seesPlayer()) &#123;            monster-&gt;setState(new Idle());        &#125;    &#125;&#125;;struct Monster &#123;    State *state = new Idle();    void update() &#123;        state-&gt;update(this);    &#125;    void setState(State *newState) &#123;        delete state;        state = newState;    &#125;&#125;;

原型模式原型模式用于复制现有的对象，且新对象的属性和类型与原来相同。如何实现？

为什么拷贝构造函数不行？

拷贝构造函数只能用于类型确定的情况，对于具有虚函数，可能具有额外成员的多态类型，会发生 object-slicing，导致拷贝出来的类型只是基类的部分，而不是完整的子类对象。
RedBall ball;Ball newball = ball;  // 错误：发生了 object-slicing！现在 newball 的类型只是 Ball 了，丢失了 RedBall 的信息


为什么拷贝指针不行？

指针的拷贝是浅拷贝，而我们需要的是深拷贝。
Ball *ball = new RedBall();Ball *newball = ball;  // 错误：指针的拷贝是浅拷贝！newball 和 ball 指向的仍然是同一对象


需要调用到真正的构造函数，同时又基于指针

Ball *ball = new RedBall();Ball *newball = new RedBall(*dynamic_cast&lt;RedBall *&gt;(ball));  // 可以，但是这里显式写出了 ball 内部的真正类型，违背了开闭原则


将拷贝构造函数封装为虚函数

原型模式将对象的拷贝方法作为虚函数，返回一个虚接口的指针，避免了直接拷贝类型。但虚函数内部会调用子类真正的构造函数，实现深拷贝。
对于熟悉工厂模式的同学：原型模式相当于把每个对象变成了自己的工厂，只需要有一个现有的对象，就能不断复制出和他相同类型的对象来。
struct Ball &#123;    virtual Ball *clone() = 0;&#125;;struct RedBall : Ball &#123;    Ball *clone() override &#123;        return new RedBall(*this);  // 调用 RedBall 的拷贝构造函数    &#125;&#125;;struct BlueBall : Ball &#123;    Ball *clone() override &#123;        return new BlueBall(*this);  // 调用 BlueBall 的拷贝构造函数    &#125;    int someData;  // 如果有成员变量，也会一并被拷贝到&#125;;

好处是，调用者无需知道具体类型，只需要他是 Ball 的子类，就可以克隆出一份完全一样的子类对象来，且返回的也是指针，不会发生 object-slicing。
Ball *ball = new RedBall();...Ball *newball = ball-&gt;clone();  // newball 的类型仍然是 RedBall

clone 返回为智能指针struct Ball &#123;    virtual unique_ptr&lt;Ball&gt; clone() = 0;&#125;;struct RedBall : Ball &#123;    unique_ptr&lt;Ball&gt; clone() override &#123;        return make_unique&lt;RedBall&gt;(*this);  // 调用 RedBall 的拷贝构造函数    &#125;&#125;;struct BlueBall : Ball &#123;    unique_ptr&lt;Ball&gt; clone() override &#123;        return make_unique&lt;BlueBall&gt;(*this);  // 调用 BlueBall 的拷贝构造函数    &#125;    int someData;  // 如果有成员变量，也会一并被拷贝到新对象中&#125;;

这样就保证了内存不会泄漏。
如果调用者需要的是 shared_ptr，怎么办？
答：unique_ptr 可以隐式转换为 shared_ptr。
如果调用者需要的是手动 delete 的原始指针，怎么办？
答：unique_ptr 可以通过 release，故意造成一次内存泄漏，成为需要手动管理的原始指针。
CRTP 模式自动实现 cloneCRTP（Curiously Recurring Template Pattern）是一种模板元编程技术，它可以在编译期间把派生类的类型作为模板参数传递给基类，从而实现一些自动化的功能。
特点是，继承一个 CRTP 类时，需要把子类本身作为基类的模板参数。
并不会出现循环引用是因为，用到子类的具体类型是在基类的成员函数内部，而不是直接在基类内部，而模板类型的成员函数的实例化是惰性的，用到了才会实例化。
template &lt;class Derived&gt;struct Pet &#123;    void feed() &#123;        Derived *that = static_cast&lt;Derived *&gt;(this);        that-&gt;speak();        that-&gt;speak();    &#125;&#125;;struct CatPet : Pet&lt;CatPet&gt; &#123;    void speak() &#123;        puts(&quot;Meow!&quot;);    &#125;&#125;;struct DogPet : Pet&lt;DogPet&gt; &#123;    void speak() &#123;        puts(&quot;Bark!&quot;);    &#125;&#125;;

一般的象牙塔理论家教材中都会告诉你，CRTP 是用于取代虚函数，更高效地实现模板模式，好像 CRTP 就和虚函数势不两立。
但小彭老师的编程实践中，CRTP 常常是和虚函数一起出现的好搭档。
例如 CRTP 可以帮助原型模式实现自动化定义 clone 虚函数，稍后介绍的访问者模式中也会用到 CRTP。
struct Ball &#123;    virtual unique_ptr&lt;Ball&gt; clone() = 0;&#125;;template &lt;class Derived&gt;struct BallImpl : Ball &#123;  // 自动实现 clone 的辅助工具类    unique_ptr&lt;Ball&gt; clone() override &#123;        Derived *that = static_cast&lt;Derived *&gt;(this);        return make_unique&lt;Derived&gt;(*that);    &#125;&#125;;struct RedBall : BallImpl&lt;RedBall&gt; &#123;    // unique_ptr&lt;Ball&gt; clone() override &#123;       // BallImpl 自动实现的 clone 等价于    //     return make_unique&lt;RedBall&gt;(*this);  // 调用 RedBall 的拷贝构造函数    // &#125;&#125;;struct BlueBall : BallImpl&lt;BlueBall&gt; &#123;    // unique_ptr&lt;Ball&gt; clone() override &#123;       // BallImpl 自动实现的 clone 等价于    //     return make_unique&lt;BlueBall&gt;(*this);  // 调用 BlueBall 的拷贝构造函数    // &#125;&#125;;

在小彭老师自主研发的 Zeno 中，对象类型 zeno::IObject 的深拷贝就运用了 CRTP 加持的原型模式。
组件模式游戏中的物体（游戏对象）通常由多个组件组成，例如，一个角色可能由“角色控制器”、“角色外观”、“角色动画”等组件组成，一个子弹可能由“子弹物理”、“子弹外观”等组件组成。
组件模式是游戏开发领域最重要的设计模式，它将游戏对象分为多个组件，每个组件只关心自己的逻辑，而不关心其他组件的逻辑。
蹩脚的游戏开发者（通常是 985 量产出来的象牙塔巨婴）会把每个组件写成一个类，然后使用“多重继承”继承出一个玩家类来，并恬不知耻地声称“我也会组件模式了”。
然而，这样的缺点有：

游戏开发中普遍涉及到 update 函数，而玩家类的 update 需要轮流调用每个组件的 update 函数。

而多重继承一旦遇到重名的 update 函数，会直接报错 “有歧义的函数名” 摆烂不干了，需要你手写新的 update 函数。
struct Player : PlayerController, PlayerAppearance, PlayerAnimation &#123;    void update() &#123;        PlayerController::update();        PlayerAppearance::update();        PlayerAnimation::update();    &#125;&#125;;


C++（和大多数非脚本语言都）不支持运行时添加或删除基类，也就是说，如果要添加一个新角色，或是修改现有角色的逻辑，就需要重新编译一遍整个游戏的源码。

在网络游戏中，更新 DLL 和更新资产（图片、音频、模型等）是完全不同的。

对于服务端而言，更新 DLL 需要停机更新，更新资产不需要，DLL 可以被编程允许动态加载新的贴图。
对于客户端而言，更新 DLL 需要重新走一遍很长的 App 审核流程（因为直接运行于手机上的 C++ 可以轻松植入病毒），而更新资产的审核流程短得多，甚至干脆无需审核。

因此，游戏开发者很少会把游戏逻辑直接写死在 C++ 中，这会让更新游戏逻辑（例如修复 BUG）需要停机更新。（例如明日方舟每次停机更新都会给玩家发 200 合成玉）
你经常看到游戏领域的 “C++ 开发岗” 实际上是 “解释器开发”。
游戏开发者会把经常需要维护和更新的游戏逻辑写在如 Lua、Python 等脚本语言中，然后在 C++ 中集成一个 Lua、Python 解释器，根据解释器的调用结果，动态创建出 C++ 对象，然后把这些 C++ 对象当作组件添加到游戏对象上。
当出现 BUG 时，只需要修改这些脚本语言的代码，然后以“资产”的形式，快速走一遍审核流程，就可以修复 BUG，无需停机更新。（例如明日方舟有时候会“资源已过期”“正在下载资源”，有时是更新了图片资源，也可能是在脚本语言里动态修复了 BUG）

Java 和 C# 都没有多重继承。你让人家基于 C# 的 Unity 怎么活？

因此，真正的组件模式都会允许动态插入组件，而不是编译期写死。除非你是某些象牙塔的一次性沙雕大作业。
游戏对象组件化后，可以灵活地组合出不同的游戏对象，而不必为每一种组合都写一个类。
struct Component &#123;    virtual void update(GameObject *go) = 0;    virtual ~Component() = default;  // 注意！&#125;;struct GameObject &#123;    vector&lt;Component *&gt; components;    void add(Component *component) &#123;        components.push_back(component);    &#125;    void update() &#123;        for (auto &amp;&amp;c: components) &#123;            c-&gt;update(this);        &#125;    &#125;&#125;;

注意：Component 的析构函数必须为虚函数。否则，当 Component 被 delete 时，只会调用到 Component 这个基类的析构函数，而不会调用到子类的析构函数。
否则，如果你的子类有 string、vector 这种持有内存资源的容器类，会发生内存泄漏，导致游戏运行越久内存占用越大。
神奇的是，如果你的 Component 全部都是用 make_shared 创建的，那就没有内存泄漏了，这得益于 shared_ptr 会对 deleter 做类型擦除。 make_unique 和 new 创建的就会泄漏，因为他们 delete 时是以基类指针去 delete 的，而 shared_ptr 会在构造时就记住子类的 deleter。
所有组件，都支持 update（每帧更新）操作：
struct Movable : Component &#123;    glm::vec3 position;    glm::vec3 velocity;    void update(GameObject *go) override &#123;        position += velocity * dt;    &#125;&#125;;

struct LivingBeing : Component &#123;    int ageLeft;    void update(GameObject *go) override &#123;        if (ageLeft &lt; 0)            go-&gt;kill();        else            ageLeft -= 1;    &#125;&#125;;

组件的创建组件有两种创建方式：

组件作为一个普通对象，由 GameObject 的构造函数创建。

struct Player : GameObject &#123;    Movable *movable;    LivingBeing *livingBeing;    PlayerController *playerController;    PlayerAppearance *playerAppearance;    Player() &#123;        movable = new Movable();        livingBeing = new LivingBeing(42);        playerController = new PlayerController();        playerAppearance = new PlayerAppearance();        add(movable);        add(livingBeing);        add(playerController);        add(playerAppearance);    &#125;&#125;;


不再需要定义 Player 类及其构造函数了，只需一个普通函数创建具有 Player 所需所有组件的 GameObject 对象即可。

GameObject *makePlayer() &#123;    GameObject *go = new GameObject();    go-&gt;add(new Movable());    go-&gt;add(new LivingBeing(42));    go-&gt;add(new PlayerController());    go-&gt;add(new PlayerAppearance());    return go;&#125;

正经游戏引擎都采用后者，不用添加 C++ 源码，只是从 xml 等配置文件读取每个类所依赖的组件，就能创建新的玩家类，方便动态更新游戏逻辑而无需重新发布 dll。
组件之间如何通信缺点是，组件之间的通信需要通过 GameObject 来实现，而 GameObject 并不知道它的组件是什么，这样就无法直接访问组件的成员。
例如，PlayerController 组件想要改变 Movable 组件的 velocity，就无法直接改。
struct PlayerController : Component &#123;    void update(GameObject *go) override &#123;        if (isKeyPressed(GLFW_KEY_W)) &#123;            go-&gt;velocity.y += 1; // 错误！velocity 是 Movable 组件的成员，而不是 GameObject 里直接有的        &#125;        if (isKeyPressed(GLFW_KEY_S)) &#123;            go-&gt;velocity.y -= 1;        &#125;        if (isKeyPressed(GLFW_KEY_A)) &#123;            go-&gt;velocity.x -= 1;        &#125;        if (isKeyPressed(GLFW_KEY_D)) &#123;            go-&gt;velocity.x += 1;        &#125;    &#125;&#125;;

如何解决组件之间通信难的问题？

把常用的字段，例如 position 和 velocity 直接放在 GameObject 里，供所有组件直接访问。

struct GameObject &#123;    glm::vec3 position;    glm::vec3 velocity;    ...&#125;;


允许用户根据其他组件的类型，直接获取出其他组件的指针，即可访问其成员。

struct PlayerController : Component &#123;    void update(GameObject *go) override &#123;        Movable *movable = go-&gt;getComponent&lt;Movable&gt;();        if (!movable) &#123;            throw runtime_error(&quot;这个对象似乎不支持移动&quot;);        &#125;        if (isKeyPressed(GLFW_KEY_W)) &#123;            movable-&gt;velocity.y += 1;        &#125;        if (isKeyPressed(GLFW_KEY_S)) &#123;            movable-&gt;velocity.y -= 1;        &#125;        if (isKeyPressed(GLFW_KEY_A)) &#123;            movable-&gt;velocity.x -= 1;        &#125;        if (isKeyPressed(GLFW_KEY_D)) &#123;            movable-&gt;velocity.x += 1;        &#125;    &#125;&#125;;

然而，getComponent 如何实现？
struct GameObject &#123;    template &lt;class T&gt;    T *getComponent() &#123;        for (auto &amp;&amp;c: components) &#123;            if (T *t = dynamic_cast&lt;T *&gt;(c)) &#123;                return t;            &#125;        &#125;        return nullptr;    &#125;&#125;;

用到了 dynamic_cast，这是比较低效的一种实现方式，而且也不符合开闭原则。
更好的实现方式是利用 typeid 做 map 的键，加速查找。没有性能问题，但依然不符合开闭原则。
struct GameObject &#123;    unordered_map&lt;type_index, Component *&gt; components;    template &lt;class T&gt;    T *getComponent() &#123;        if (auto it = components.find(typeid(T)); it != components.end()) &#123;            return dynamic_cast&lt;T *&gt;(it-&gt;second);        &#125; else &#123;            return nullptr;        &#125;    &#125;    void add(Component *component) &#123;        components[typeid(*component)] = component;    &#125;&#125;;


让 PlayerController 发出指定类型的消息对象，由 Movable 检查并处理。

消息类型也是多态的，初学者可以先通过 dynamic_cast 实现类型检查。稍后我们会介绍更专业的访问者模式。
通常来说，我们只能把子类指针转换为基类指针。
而 dynamic_cast 可以把基类指针转换为子类指针。
如果他指向的对象确实就是那个子类类型的话，就正常返回子类指针了。
否则，如果类型不匹配，dynamic_cast 会返回 nullptr。只需判断返回的指针是不是 nullptr 就知道是否类型匹配了。
观察者模式struct Message &#123;    virtual ~Message() = default;  // C++ 规定：只有多态类型才能 dynamic_cast，这里我们用不到虚函数，那就只让析构函数为虚函数，即可使 Message 变为多态类型&#125;;struct MoveMessage : Message &#123;    glm::vec3 velocityChange;&#125;;struct Component &#123;    virtual void update(GameObject *go) = 0;    virtual void handleMessage(Message *msg) = 0;    virtual ~Component() = default;&#125;;struct Movable : Component &#123;    glm::vec3 position;    glm::vec3 velocity;    void handleMessage(Message *msg) override &#123;        // 所有不同的消息类型都会进入此函数        if (MoveMessage *mm = dynamic_cast&lt;MoveMessage *&gt;(msg)) &#123;            // 但只有真正类型为 MoveMessage 的消息会被处理            velocity += mm-&gt;velocityChange;        &#125;    &#125;&#125;;struct PlayerController : Component &#123;    void update(GameObject *go) override &#123;        if (isKeyPressed(GLFW_KEY_W)) &#123;            MoveMessage mm;            mm.velocityChange.y += 1;            go-&gt;send(&amp;mm);        &#125;        if (isKeyPressed(GLFW_KEY_S)) &#123;            MoveMessage mm;            mm.velocityChange.y -= 1;            go-&gt;send(&amp;mm);        &#125;        if (isKeyPressed(GLFW_KEY_A)) &#123;            MoveMessage mm;            mm.velocityChange.x -= 1;            go-&gt;send(&amp;mm);        &#125;        if (isKeyPressed(GLFW_KEY_D)) &#123;            MoveMessage mm;            mm.velocityChange.x += 1;            go-&gt;send(&amp;mm);        &#125;    &#125;&#125;;

struct GameObject &#123;    vector&lt;Component *&gt; components;    void add(Component *component) &#123;        components.push_back(component);    &#125;    void update() &#123;        for (auto &amp;&amp;c: components) &#123;            c-&gt;update(this);        &#125;    &#125;    void send(Message *msg) &#123;        for (auto &amp;&amp;c: components) &#123;            c-&gt;handleMessage(msg);        &#125;    &#125;&#125;;

这就是所谓的观察者模式，由于每个组件都可以收到所有消息，因此，可以实现组件之间的通信。
但这样做的缺点是，每个组件都需要处理所有消息，不论是否是自己需要的，如果组件数量多，消息类型又多，就会出现性能问题。
发布-订阅模式发布-订阅模式是观察者模式的升级版，由一个中心的事件总线来管理消息的分发。事件总线通常作为 GameObject 的成员出现。
每个组件可以订阅自己感兴趣的消息类型，当事件总线收到消息时，只把消息分发给订阅者，而不是所有组件。
struct GameObject &#123;    vector&lt;Component *&gt; components;    unordered_map&lt;type_index, vector&lt;Component *&gt;&gt; subscribers;  // 事件总线    template &lt;class EventType&gt;    void subscribe(Component *component) &#123;        subscribers[type_index(typeid(EventType))].push_back(component);    &#125;    template &lt;class EventType&gt;    void send(EventType *msg) &#123;        for (auto &amp;&amp;c: subscribers[type_index(typeid(EventType))]) &#123;            c-&gt;handleMessage(msg);        &#125;    &#125;    void add(Component *component) &#123;        components.push_back(component);        component-&gt;subscribeMessages(this);    &#125;    void update() &#123;        for (auto &amp;&amp;c: components) &#123;            c-&gt;update(this);        &#125;    &#125;&#125;;struct Component &#123;    virtual void update(GameObject *go) = 0;    virtual void subscribeMessages(GameObject *go) = 0;    virtual void handleMessage(Message *msg) = 0;    virtual ~Component() = default;&#125;;struct Movable : Component &#123;    glm::vec3 position;    glm::vec3 velocity;    void subscribeMessages(GameObject *go) &#123;        go-&gt;subscribe&lt;MoveMessage&gt;(this);    &#125;    void handleMessage(Message *msg) override &#123;        if (MoveMessage *mm = dynamic_cast&lt;MoveMessage *&gt;(msg)) &#123;            velocity += mm-&gt;velocityChange;        &#125;    &#125;&#125;;struct PlayerController : Component &#123;    void update(GameObject *go) override &#123;        if (isKeyPressed(GLFW_KEY_W)) &#123;            MoveMessage mm;            mm.velocityChange.y += 1;            go-&gt;send(&amp;mm);        &#125;        if (isKeyPressed(GLFW_KEY_S)) &#123;            MoveMessage mm;            mm.velocityChange.y -= 1;            go-&gt;send(&amp;mm);        &#125;        if (isKeyPressed(GLFW_KEY_A)) &#123;            MoveMessage mm;            mm.velocityChange.x -= 1;            go-&gt;send(&amp;mm);        &#125;        if (isKeyPressed(GLFW_KEY_D)) &#123;            MoveMessage mm;            mm.velocityChange.x += 1;            go-&gt;send(&amp;mm);        &#125;        if (isKeyPressed(GLFW_KEY_SPACE)) &#123;            JumpMessage jm;            go-&gt;send(&amp;jm);        &#125;    &#125;&#125;;

这样，就可以实现组件之间的按需通信。
访问者模式struct Message &#123;    virtual ~Message() = default;&#125;;struct MoveMessage &#123;    glm::vec3 velocityChange;&#125;;struct JumpMessage &#123;    double jumpHeight;&#125;;

如何定义对所有不同类型消息的处理方式？
struct MessageVisitor;  // 前向声明struct Message &#123;    virtual void accept(MessageVisitor *visitor) = 0;    virtual ~Message() = default;&#125;;struct MoveMessage &#123;    glm::vec3 velocityChange;    void accept(MessageVisitor *visitor) override &#123;        visitor-&gt;visit(this);  // 会调用到 visit(MoveMessage *mm) 这个重载    &#125;&#125;;struct JumpMessage &#123;    double jumpHeight;    void accept(MessageVisitor *visitor) override &#123;        visitor-&gt;visit(this);  // 会调用到 visit(JumpMessage *mm) 这个重载    &#125;&#125;;struct MessageVisitor &#123;    virtual void visit(MoveMessage *mm) &#123;&#125;  // 默认不做任何处理    virtual void visit(JumpMessage *jm) &#123;&#125;  // 默认不做任何处理&#125;;struct Movable : MessageVisitor &#123;    glm::vec3 position;    glm::vec3 velocity;    void handleMessage(Message *msg) &#123;        msg-&gt;accept(this);    &#125;    void visit(MoveMessage *mm) override &#123;        velocity += mm-&gt;velocityChange;    &#125;    void visit(JumpMessage *jm) override &#123;        velocity.y += sqrt(2 * 9.8 * jm-&gt;jumpHeight);    &#125;&#125;;

这就是访问者模式，同时用到了面向对象的虚函数和重载机制，实现了对所有不同类型消息都能定制一个处理方式，而不用通过低效的 dynamic_cast 判断消息类型。
访问者模式是否符合开闭原则呢？
当我们新增一种消息类型时，需要修改的地方有：

新增消息类型
在 MessageVisitor 中添加一个 visit 的重载

当我们新增一种组件类型时，需要修改的地方有：

新增组件类型

这三项修改都是符合开闭原则的，并不会出现牵一发而动全身的情况。
但每个组件都要处理所有消息，这就是一个不符合开闭原则的设计，因此我们让所有的 visit 虚函数有一个默认实现，那就是什么都不做。这样当新增消息类型时，虽然需要每个组件都重新编译了，但是程序员无需修改任何代码，源码级别上，是满足开闭原则的。
访问者模式通常用于 acceptor 数量有限，但 visitor 的组件类型千变万化的情况。

如果消息类型有限，组件类型可能经常增加，那需要把组件类型作为 visitor，消息类型作为 acceptor。
如果组件类型有限，消息类型可能经常增加，那需要把消息类型作为 visitor，组件类型作为 acceptor。
常作为 acceptor 的有：编译器开发中的 IR 节点（代码中间表示），游戏与 UI 开发中的消息类型。
常作为 visitor 的有：编译器开发中的优化 pass（会修改 IR 节点），游戏与 UI 开发中的接受消息组件类型。

但是每个组件都要实现 accept 的重载，内容完全一样，出现了代码重复。
Java 的模板是 type-erasure 的，对此束手无策。而 C++ 的模板是 refined-generic，可以利用 CRTP 自动实现这部分：
struct Message &#123;    virtual void accept(MessageVisitor *visitor) = 0;    virtual ~Message() = default;&#125;;template &lt;class Derived&gt;struct MessageImpl : Message &#123;    void accept(MessageVisitor *visitor) override &#123;        static_assert(std::is_base_of_v&lt;MessageImpl, Derived&gt;);        visitor-&gt;visit(static_cast&lt;Derived *&gt;(this));    &#125;&#125;;struct MoveMessage : MessageImpl&lt;MoveMessage&gt; &#123;    glm::vec3 velocityChange;    // 自动实现了 accept 函数&#125;;struct JumpMessage : MessageImpl&lt;JumpMessage&gt; &#123;    double jumpHeight;&#125;;

在小彭老师自主研发的 Zeno 中，ZFX 编译器的 IR 优化系统就运用了 CRTP 加持的访问者模式。
MVC 模式设计模式是一个巨大的话题，本期先讲到这里，下集我们继续介绍 UI 开发中大名鼎鼎的 MVC 模式。
MVC 模式是一种架构模式，它将应用程序分为三个核心部分：模型（Model）、视图（View）和控制器（Controller），通过分离应用程序的输入、处理和输出来提高应用程序的可维护性和可扩展性。

模型（Model）：负责处理数据和业务逻辑，通常由数据结构和数据库组成。
视图（View）：负责展示数据和用户界面，通常由 HTML、CSS 和 JavaScript 组成。
控制器（Controller）：负责处理用户交互和调度模型和视图，通常由后端语言（如 PHP、Java 等）实现。

MVC 模式的优点：

低耦合：模型、视图和控制器之间的职责清晰，可以更容易地进行单独的修改和维护。
可扩展性：由于模型、视图和控制器之间的低耦合性，可以更容易地添加新的功能和组件。
可维护性：分离了不同的职责，使得代码更容易理解和维护。

五、源码解析和实践感悟5.1 源码解析策略模式的核心机制——虚函数表多态策略模式最精妙的 C++ 实现就是虚函数替换。回顾文中的 reduce 函数：
int reduce(vector&lt;int&gt; v, Reducer* reducer) &#123;    int res = reducer-&gt;init();        // 虚函数调用①    for (int i = 0; i &lt; v.size(); i++) &#123;        res = reducer-&gt;add(res, v[i]); // 虚函数调用②    &#125;    return res;&#125;

reducer-&gt;add() 表面是一行代码，背后是两次指针解引用：reducer-&gt;vtable[1]()。新增策略（如 MinReducer）零修改 reduce 函数——这是开闭原则的经典体现。
观察者模式与发布-订阅的 type_index 路由// 事件总线的核心：type_index 路由表template &lt;class EventType&gt;void send(EventType* msg) &#123;    auto it = subscribers.find(std::type_index(typeid(EventType)));    if (it != subscribers.end()) &#123;        for (auto* c : it-&gt;second) &#123;            c-&gt;handleMessage(msg);  // 只通知订阅者        &#125;    &#125;&#125;

type_index 作为路由键，将 O(n) 的广播优化为 O(1) 的定向分发。dynamic_cast 检查在发布-订阅中仅需一次 typeid 比对，性能远优于观察者的逐个 cast。
组件模式中 getComponent 的 typeid 实现template &lt;class T&gt;T* getComponent() &#123;    auto it = components.find(typeid(T));    if (it != components.end()) &#123;        return static_cast&lt;T*&gt;(it-&gt;second);  // 已知类型安全，无需 dynamic_cast    &#125;    return nullptr;&#125;

组件注册时用 typeid(*component) 做键，查找时用 typeid(T) 精确匹配，O(1) 查找 + static_cast（零开销），比遍历 dynamic_cast 高效得多。
5.2 实践经验
策略模式 + 工厂模式 &#x3D; 可插拔算法库：策略定义”做什么”、工厂定义”谁来做”，组合到一起可实现运行时切换算法
组件模式是 ECS 的基础：Unity 等引擎的 GameObject + Component 就是组件模式，扩展新功能只需加新组件
CRTP 替代虚函数有陷阱：CRTP 在编译期绑定，无法实现运行时多态（不能放进 vector&lt;Base*&gt;），仅适用于类型已知的场景
观察者模式慎用：组件间广播消息虽解耦但难调试——消息流不透明，容易形成”消息风暴”
享元模式不只收游戏：字符串 intern、线程池复用、protobuf arena 都是享元思想
模板模式 vs 策略模式的选择口诀：一个变数用模板模式，多个独立变数用策略模式

六、面试准备6.1 面试 Q&amp;AQ1: 策略模式、模板方法模式、状态模式三者如何区分？



模式
